    "detailedBiographyBn": "হযরত আইয়াশ ইবনে আবি রাবিয়া (রা.) ছিলেন কুরাইশ বংশের অন্যতম ধনী ও প্রভাবশালী নেতা। তিনি ছিলেন ইসলামের কট্টর শত্রু আবু জাহেলের বৈপিত্রেয় ভাই (একই মায়ের সন্তান)। মক্কার প্রাথমিক দিনগুলোতে দারুল আরকামে প্রবেশ করে তিনি ইসলাম গ্রহণ করেন।\n\nহিজরতের সময় যখন উমর ইবনুল খাত্তাব (রা.) মদিনার উদ্দেশ্যে রওনা হন, আইয়াশ তাঁর সাথে হিজরত করেন। কিন্তু মদিনার কুবা পল্লীতে পৌঁছার পর আবু জাহেল ও হারিস ইবনে হিশাম মক্কা থেকে ছুটে এসে আইয়াশের কাছে মিথ্যার আশ্রয় নেয়। তারা বলল: \"তোমার মা কসম খেয়েছে যতক্ষণ তোমাকে ফিরে না দেখবে, ততক্ষণ সে ছায়ায় বসবে না এবং মাথায় চিরুনি দেবে না!\" উমর (রা.) আইয়াশকে সতর্ক করে বললেন: \"হে আইয়াশ! আল্লাহর কসম, এটা তোমার ভাইয়ের ছলনা! তীব্র গরমে অতিষ্ঠ হলে তোমার মা নিজেই ছায়ায় বসবে এবং মাথায় উকুন হলে নিজেই চিরুনি দেবে!\" কিন্তু মায়ের প্রতি মমতাবোধে আইয়াশ উমরের চমৎকার উটের ওপর চড়ে মক্কায় ফিরতে রাজি হলেন।\n\nপথিমধ্যে আবু জাহেল ও তার সাথীরা ধূর্ততার সাথে আইয়াশকে আক্রমণ করে রশি দিয়ে বেঁধে ফেলে এবং মক্কায় এনে অন্ধকার প্রকোষ্ঠে লোহার শিকল পরিয়ে উল্লাস প্রকাশ করে। মক্কায় দীর্ঘকাল তিনি নির্মম নির্যাতনের মুখে বন্দি ছিলেন। রাসুলুল্লাহ (সা.) মদিনায় প্রতিদিন ফজরের সালাতে কুনুতে নাজেলা পড়ে আইয়াশ ও অন্যান্য মজলুমদের মুক্তির জন্য আল্লাহর দরবারে ফরিয়াদ করতেন। পরবর্তীতে ওয়ালিদ ইবনুল মুগিরা মক্কায় গিয়ে গোপনে তাঁর শিকল কেটে তাঁকে মদিনায় উদ্ধার করে আনেন। ১৫ হিজরিতে ইয়ারমুকের রক্তক্ষয়ী প্রান্তরে রোমানদের বিরুদ্ধে লড়াইয়ে তিনি বীরবিক্রমে শাহাদাত বরণ করেন।",
