    "detailedBiographyBn": "হযরত আনাস ইবনে নাদর (রা.) ছিলেন মদিনার বনু নাজ্জার গোত্রের এক অত্যন্ত সাহসী সাহাবি। তিনি কোনো কারণে বদর যুদ্ধে অংশ নিতে পারেননি। এতে তিনি আজীবন অত্যন্ত আক্ষেপ করতেন এবং আল্লাহর দরবারে ওয়াদা করে বলতেন: \"আল্লাহর কসম! যদি আল্লাহ আমাকে রাসুল (সা.)-এর সাথে কোনো যুদ্ধের ময়দানে হাজির হওয়ার সুযোগ দেন, তবে আল্লাহ দেখতে পাবেন আমি কী বীরত্ব দেখাই!\"\n\n৩ হিজরিতে উহুদের যুদ্ধে যখন সাহাবিদের একাংশের ভুলের কারণে মুসলিম বাহিনীতে বিপর্যয় নেমে এলো এবং শয়তান চিৎকার করে রটিয়ে দিল যে মুহাম্মদ (সা.) নিহত হয়েছেন, তখন বহু সাহাবি ময়দানের এক কোণে অস্ত্র ফেলে হতাশ হয়ে বসে পড়লেন। আনাস ইবনে নাদর তাঁদের কাছে এসে গর্জে উঠলেন: \"তোমরা বসে আছ কেন?\" তাঁরা বললেন: \"রাসুলুল্লাহ (সা.) তো শহীদ হয়ে গেছেন!\" আনাস ইবনে নাদর বললেন: \"রাসুল যদি শহীদ হয়েই যান, তবে তাঁর পরে বেঁচে থেকে তোমাদের কী লাভ? ওঠো! এবং রাসুলুল্লাহ (সা.) যে সত্যের ওপর জীবন দিয়েছেন, তোমরাও সেই সত্যের ওপর জীবন দিয়ে দাও!\"\n\nএরপর তিনি সা’দ ইবনে মুআযের পাশ দিয়ে দ্রুত শত্রুসেনার দিকে ধেয়ে যাওয়ার সময় চিৎকার করে বললেন: \"হে সা’দ! আহা জান্নাত! কাবার রবের কসম, আমি উহুদের ওপার থেকে জান্নাতের সুঘ্রাণ পাচ্ছি!\" এরপর তিনি একা কাফেরদের বিশাল ব্যূহের মধ্যে সিংহের মতো ঝাঁপিয়ে পড়েন এবং শহীদ হন। যুদ্ধশেষে তাঁর দেহে ৮০টিরও বেশি তলোয়ার, তীর ও বর্শার আঘাত পাওয়া যায়। তাঁর চেহারা এত বিকৃত হয়ে গিয়েছিল যে কেউ তাঁকে চিনতে পারেনি; কেবল তাঁর বোন রুবাইয়ি তাঁর আঙুলের ডগার একটি বিশেষ চিহ্ন দেখে নিজের ভাইকে শনাক্ত করেছিলেন। তাঁর এই নিঃস্বার্থ বীরত্বের শানে স্বয়ং আল্লাহ সূরা আহযাবের ২৩ নম্বর আয়াত নাজিল করেন।",
