    "summaryBn": "উমর ফারুক (রা.)-এর সুযোগ্য পুত্র; রাসুলুল্লাহ (সা.)-এর সুন্নাহ হুবহু অনুসরণে সাহাবিদের মধ্যে শীর্ষে ছিলেন; যিনি ২,৬৩০টি হাদিস নিখুঁতভাবে বর্ণনা করেছেন এবং ফিতনার যুগে ক্ষমতা ও রক্তপাত থেকে সম্পূর্ণ দূরে থেকেছেন।",
    "detailedBiographyBn": "হযরত আব্দুল্লাহ ইবনে উমর (রা.) ছিলেন ইসলামের দ্বিতীয় খলিফা উমর ইবনুল খাত্তাব (রা.)-এর জ্যেষ্ঠ পুত্র। শৈশবেই তিনি পিতার সাথে ইসলাম গ্রহণ করেন এবং অল্প বয়সে মদিনায় হিজরত করেন। বদর ও উহুদের যুদ্ধে মাত্র ১৩-১৪ বছর বয়সে তলোয়ার নিয়ে লড়াই করতে চাইলে রাসুল (সা.) কম বয়সের কারণে তাঁকে ফিরিয়ে দেন। পরবর্তীতে খন্দকের যুদ্ধে ১৫ বছর বয়সে তিনি প্রথমবার যুদ্ধের অনুমতি পান।\n\nইবনে উমর (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর প্রতিটি ক্ষুদ্রাতিক্ষুদ্র সুন্নাহ অনুসরণের এক অনন্য প্রতীক। রাসুল (সা.) সফরের পথে যেখানে বিশ্রাম নিয়েছিলেন, যে গাছের নিচে বসেছিলেন, যেখানে দাঁড়িয়ে উটের পিঠে সালাত পড়েছিলেন—ইবনে উমর বহু বছর পরও হুবহু সেই স্থানে গিয়ে সেভাবে বসতেন এবং সালাত আদায় করতেন! সাহাবিরা বলতেন: \"সুন্নাহর ব্যাপারে ইবনে উমরের চেয়ে বেশি সতর্ক মানুষ আর কেউ ছিল না।\"\n\nতিনি ছিলেন উম্মাহর অন্যতম শ্রেষ্ঠ ফকিহ ও মুহাদ্দিস (২,৬৩০টি হাদিস বর্ণিত)। তিনি ৬০ বছর ধরে মদিনায় ফতোয়া প্রদান করেন। সাহাবিদের মধ্যকার রাজনৈতিক গৃহযুদ্ধে তিনি কোনো পক্ষের ওপর অস্ত্র তুলতে সম্পূর্ণ অস্বীকার করেন। খলিফা হওয়ার একাধিক প্রস্তাব আসা সত্ত্বেও তিনি তা প্রত্যাখ্যান করেন। কোনো ক্রীতদাসকে মসজিদে সুন্দরভাবে নামাজ পড়তে দেখলে তিনি তৎক্ষণাৎ তাকে আজাদ করে দিতেন। এভাবে তিনি জীবনে এক হাজারেরও বেশি দাসকে মুক্ত করেছিলেন।",
    "islamAcceptanceBn": "পিতা উমরের সাথেই বাল্যকালে মক্কায় ইসলাম গ্রহণ করেন এবং মদিনায় হিজরত করেন।",
