        "story": "কিশোর বয়সে ইবনে উমর মসজিদে নববীতে ঘুমাতেন। একদিন স্বপ্নে দেখলেন দুজন ফেরেশতা তাঁর হাত ধরে জাহান্নামের কিনারায় নিয়ে গেছেন যা একটি বাঁধানো কুয়োর মতো এবং তার ভেতর চেনা কিছু কাফের ঝুলছে। তিনি ভয়ে চিৎকার করে বললেন: \"আউজু বিল্লাহি মিনান নার!\" (আমি জাহান্নাম থেকে আল্লাহর আশ্রয় চাই!)। এমন সময় তৃতীয় এক ফেরেশতা এসে বলল: \"ভয় পেয়ো না, তুমি এর জন্য নও।\" ঘুম থেকে উঠে তিনি বোন হাফসা (রা.)-কে বললেন এবং হাফসা রাসুল (সা.)-কে জানালেন। রাসুলুল্লাহ (সা.) শুনে বললেন: \"আব্দুল্লাহ কতই না উত্তম মানুষ! যদি সে রাতে নিয়মিত তাহাজ্জুদের সালাত আদায় করত!\" ইবনে উমর বলেন: \"রাসুলের এই কথা শোনার পর থেকে জীবনের শেষ দিন পর্যন্ত রাতের সামান্য অংশ ছাড়া আমি আর কখনো ঘুমাইনি!\""
