    "birthAndDeathBn": "জন্ম: মক্কা | শাহাদাত: ১৫ হিজরি (কাদিসিয়ার যুদ্ধ)",
    "summaryBn": "মক্কার দৃষ্টিহীন সাহাবি, যাঁর কারণে মহান আল্লাহ পবিত্র কুরআনের পুরো সূরা ‘আবাসা’ নাজিল করেছিলেন; যাঁর আগমনে বিশ্বনবী পরম শ্রদ্ধায় নিজের চাদর বিছিয়ে দিয়ে বলতেন: \"স্বাগতম সেই ব্যক্তিকে যাঁর জন্য স্বয়ং আমার রব আমাকে অনুযোগ করেছিলেন!\"",
    "detailedBiographyBn": "হযরত আব্দুল্লাহ ইবনে উম্মে মাকতুম (রা.) ছিলেন উম্মুল মুমিনীন খাদিজা (রা.)-এর মামাত ভাই। তিনি ছিলেন জন্মগতভাবে দৃষ্টিহীন। মক্কার সূচনাতেই তিনি ইসলাম গ্রহণ করেন।\n\nএকদিন রাসুলুল্লাহ (সা.) মক্কার শীর্ষ কুরাইশ নেতাদের (উতবাহ, শায়বা, আবু জাহেল) ইসলামের দাওয়াত দিচ্ছিলেন। ঠিক সেই মুহূর্তে অন্ধ ইবনে উম্মে মাকতুম এসে বললেন: \"হে আল্লাহর রাসুল! আমাকে দ্বীনের কিছু কথা শিক্ষা দিন!\" রাসুল (সা.) কাফেরদের মনোযোগ নষ্ট হতে পারে ভেবে সামান্য ভ্রূ কুঁচকে মুখ ফিরিয়ে নিয়েছিলেন। সাথে সাথে সাত আসমানের ওপর থেকে রাব্বুল আলামিন সূরা আবাসার প্রথম দশটি আয়াত নাজিল করে রাসুলকে মৃদু অনুযোগ করেন। এরপর থেকে রাসুল (সা.) যখনই ইবনে উম্মে মাকতুমকে দেখতেন, নিজের চাদর বিছিয়ে দিয়ে বসাতেন এবং বলতেন: \"স্বাগতম সেই ব্যক্তিকে, যাঁর সম্মানে আমার রব আমাকে সংশোধন করেছেন!\"\n\nমদিনায় হিজরতের পর তিনি বিলাল (রা.)-এর সাথে মসজিদে নববীর মুয়াজ্জিন নিযুক্ত হন। রমজানে বিলাল প্রথম আজান দিতেন সাহরির জন্য এবং ইবনে উম্মে মাকতুম ফজরের সময় দ্বিতীয় আজান দিতেন। রাসুল (সা.) যখনই কোনো সামরিক অভিযানে মদিনার বাইরে যেতেন, তখন তিনি আব্দুল্লাহ ইবনে উম্মে মাকতুমকে মদিনার অস্থায়ী গভর্নর ও মসজিদে নববীর প্রধান ইমামের দায়িত্বে রেখে যেতেন। রাসুল তাঁর জীবনে মোট ১৩ বার এই দায়িত্ব তাঁকে দিয়েছিলেন। ১৫ হিজরিতে কাদিসিয়ার যুদ্ধে তিনি অন্ধ হওয়া সত্ত্বেও কালো পতাকা হাতে ময়দানে নেমে শাহাদাত বরণ করেন।",
    "islamAcceptanceBn": "মক্কার প্রারম্ভিক যুগেই একনিষ্ঠ অন্তরে ইসলাম গ্রহণ করেন এবং কুরআনের তালিম নিতেন।",
    "keyVirtuesBn": [
      "পবিত্র কুরআনের পুরো একটি সূরা (সূরা আবাসা) যাঁর প্রসঙ্গে ও শানে অবতীর্ণ হয়েছিল।",
      "রাসুলুল্লাহ (সা.) কর্তৃক মোট ১৩ বার মদিনার গভর্নর ও প্রধান ইমাম নিযুক্ত হওয়ার অনন্য সম্মান।",
      "মসজিদে নববীর নিয়মিত মুয়াজ্জিন।",
      "অন্ধ হওয়া সত্ত্বেও কাদিসিয়ার রক্তক্ষয়ী যুদ্ধে মুসলিম বাহিনীর প্রধান পতাকা বুকে জড়িয়ে শাহাদাত বরণ।"
    ],
    "emotionalStoriesBn": [
      {
        "title": "কাদিসিয়ার ময়দানে অন্ধ পতাকাবাহীর শাহাদাত",
        "story": "১৫ হিজরিতে কাদিসিয়ার মহাযুদ্ধের প্রস্তুতি চলছে। আব্দুল্লাহ ইবনে উম্মে মাকতুম বর্ম পরে তলোয়ার হাতে হাজির হলেন। সাহাবিরা বললেন: \"হে আব্দুল্লাহ! আপনি তো অন্ধ, আল্লাহ আপনাকে যুদ্ধ থেকে অব্যাহতি দিয়েছেন!\" আব্দুল্লাহ কেঁদে ফেলে বললেন: \"আল্লাহর কসম! তোমরা আমাকে বাধা দিয়ো না! আমি চোখে দেখি না বলে যুদ্ধক্ষেত্রে কখনো পেছনে ফিরে পালাতে পারব না! মুসলিম বাহিনীর মূল কালো পতাকাটি আমার হাতে দাও, আমি শক্ত করে মাটিতে দাঁড়িয়ে পতাকা বুকে চেপে রাখব, আর তোমরা যুদ্ধ করো!\" কাদিসিয়ার ময়দানে তিনি পতাকা বুকে চেপে ধরে দাঁড়িয়ে রইলেন যতক্ষণ না তাঁর শরীর বর্শার আঘাতে ছিন্নভিন্ন হয়ে যায়। যুদ্ধ শেষে দেখা গেল পতাকার খুঁটিটি তখনো তাঁর রক্তাক্ত বুকের ভেতর শক্তভাবে বিঁধে আছে।"
      }
    ],
