    "summaryBn": "মুতার শহীদ জাফরুত তাইয়্যার (রা.)-এর জ্যেষ্ঠ পুত্র; ইসলামের ইতিহাসে আবিসিনিয়ার মাটিতে জন্ম নেওয়া প্রথম মুসলিম শিশু; আরবের সর্বশ্রেষ্ঠ দানশীল ব্যক্তিত্ব এবং যাঁর ব্যবসার জন্য স্বয়ং রাসুল (সা.) বরকতের বিশেষ দোয়া করেছিলেন।",
    "detailedBiographyBn": "হযরত আব্দুল্লাহ ইবনে জাফর (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর চাচাত ভাই বীর শহীদ জাফর ইবনে আবি তালেব (রা.) ও আসমা বিনতে উমাইসের পুত্র। তিনি ছিলেন ইসলামের ইতিহাসে প্রথম শিশু যিনি হাবশায় (আবিসিনিয়ায়) মুসলিম মুহাজিরদের কোলে জন্মগ্রহণ করেন। ৭ হিজরিতে খায়বারের সময় তিনি পিতামাতার সাথে মদিনায় আসেন।\n\nমুতার যুদ্ধে পিতা জাফর শহীদ হওয়ার পর রাসুলুল্লাহ (সা.) আব্দুল্লাহ ও তাঁর ভাইদের নিজের ঘরে নিয়ে আসেন এবং নিজ হাতে চুল কেটে পরম স্নেহে কোলে তুলে নিয়ে দোয়া করেন: \"হে আল্লাহ! জাফরের পরিবারের দেখাশোনা আপনি করুন এবং আব্দুল্লাহর ব্যবসায় প্রভূত বরকত দান করুন!\" এই দোয়ার বরকতে আব্দুল্লাহ যা-ই ক্রয়-বিক্রয় করতেন, তাতেই বিপুল লাভ হতো।\n\nতিনি ছিলেন তৎকালীন সমগ্র আরবের শীর্ষ দানবীর। আরবে প্রবাদ হয়ে গিয়েছিল: \"দানশীলতায় আব্দুল্লাহ ইবনে জাফরের কোনো জুড়ি নেই!\" কেউ কোনোদিন তাঁর দরজায় এসে খালি হাতে ফেরেনি। ঘোড়া, উট, স্বর্ণমুদ্রা তিনি অভাবীদের মাঝে নদীর মতো বিলিয়ে দিতেন। খলিফা আলী (রা.)-এর অত্যন্ত বিশ্বস্ত সহযোগী ছিলেন তিনি। কারবালার প্রান্তরে তিনি নিজে বার্ধক্যের কারণে যেতে না পারলেও তাঁর দুই প্রিয় পুত্র আউন ও মুহাম্মদকে হোসাইন (রা.)-এর সাথে পাঠিয়ে দেন এবং তাঁরা কারবালায় বীরের মতো শহীদ হন।",
    "islamAcceptanceBn": "হাবশার মাটিতে মুসলিম মুহাজিরদের প্রথম শিশু হিসেবে তাওহীদের কোলে জন্মলাভ করেন।",
