    "deathOrMartyrdomBn": "৮০ হিজরিতে মদিনায় ৯০ বছর বয়সে ইন্তেকাল করেন। মদিনার গভর্নর আব্বান ইবনে উসমান তাঁর জানাজায় ইমামতি করেন এবং জান্নাতুল বাকিতে তাঁকে দাফন করা হয়।",
