    "birthAndDeathBn": "জন্ম: মদিনা | শাহাদাত: ৮ হিজরি (মুতার যুদ্ধ, জর্ডান)",
    "summaryBn": "মদিনার আনসারদের প্রধান কবি ও আকাবার নকীব; যিনি রাসুলের প্রতিটি আদেশ পালনে নিজের জীবন বাজি রাখতেন এবং মুতার রক্তক্ষয়ী যুদ্ধে রোমানদের লক্ষাধিক সৈন্যের সামনে কবিতা আবৃত্তি করতে করতে শাহাদাত বরণ করেছিলেন।",
    "detailedBiographyBn": "হযরত আব্দুল্লাহ ইবনে রাওয়াহা (রা.) ছিলেন মদিনার খাযরাজ গোত্রের এক প্রভাবশালী নেতা, নকীব ও কবি। তিনি আকাবার উভয় শপথে উপস্থিত ছিলেন এবং বদর ও উহুদসহ সমস্ত যুদ্ধে বীরত্ব দেখান। রাসুলুল্লাহ (সা.) যখন মসজিদে কথা বলতেন, ইবনে রাওয়াহা দূর থেকে রাসুলের কথা শোনা মাত্র যেখানে ছিলেন ঠিক সেখানেই বসে পড়তেন। রাসুল তাঁর এই চরম আনুগত্য দেখে দোয়া করেছিলেন: \"আল্লাহ তোমার আনুগত্য আরও বৃদ্ধি করুন!\"\n\n৮ হিজরির মুতার যুদ্ধে রাসুলুল্লাহ (সা.) তিন হাজার মুসলিম সেনাদলের তৃতীয় সেনাপতি হিসেবে আব্দুল্লাহ ইবনে রাওয়াহাকে মনোনীত করেন এবং নির্দেশ দেন: \"যায়েদ শহীদ হলে জাফর পতাকা ধরবে, আর জাফর শহীদ হলে আব্দুল্লাহ ইবনে রাওয়াহা পতাকা ধরবে!\"\n\nমুতার প্রান্তরে পৌঁছে যখন মুসলিমরা দেখল রোমানদের বিশাল সুসজ্জিত বাহিনী এক লক্ষ সৈন্যের মহাবহর নিয়ে প্রস্তুত, তখন সাহাবিরা দ্বিধায় পড়লেন। ইবনে রাওয়াহা ঘোড়ার ওপর দাঁড়িয়ে বজ্রকণ্ঠে কবিতা আবৃত্তি করে সাহাবিদের উজ্জীবিত করে বললেন: \"হে লোকসকল! আল্লাহর কসম, আজ যে মৃত্যুকে তোমরা ভয় পাচ্ছ, সেটাই তো অন্বেষণ করে তোমরা মদিনা থেকে বের হয়েছিলে—শাহাদাত! আমরা তো কখনো সংখ্যা বা অস্ত্রের জোরে লড়াই করি না; আমরা লড়াই করি সেই দ্বীনের জোরে যা দিয়ে আল্লাহ আমাদের সম্মানিত করেছেন! চলো সামনে বাড়ো, আমাদের সামনে কেবল দুটি কল্যাণের একটি—হয়তো বিজয়, নয়তো জান্নাতী শাহাদাত!\" এরপর যায়েদ ও জাফরের শাহাদাতের পর তিনি পতাকা হাতে তুলে নেন এবং বীরদর্পে লড়াই করে শাহাদাত বরণ করেন।",
    "islamAcceptanceBn": "আকাবার প্রথম ও দ্বিতীয় শপথে অগ্রণী ভূমিকা পালন করে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
    "keyVirtuesBn": [
      "মুতার প্রান্তরে রোমানদের বিরুদ্ধে ঐতিহাসিক ভাষণে মুসলিমদের মনোবল জাগিয়ে তোলা মহাবীর।",
      "রাসুলুল্লাহ (সা.) যাঁর কবিতা শুনে অত্যন্ত প্রীত হতেন এবং কাফেরদের বিরুদ্ধে মোক্ষম জবাব মনে করতেন।",
      "মুতার যুদ্ধের তৃতীয় প্রধান সেনাপতি হিসেবে বীরোচিত শাহাদাত বরণ।"
    ],
    "emotionalStoriesBn": [
      {
        "title": "মসজিদের দরজার বাইরে রাস্তায় বসে পড়া",
        "story": "একদিন আব্দুল্লাহ ইবনে রাওয়াহা মসজিদে নববীর দিকে আসছিলেন। রাসুলুল্লাহ (সা.) তখন মিম্বারে দাঁড়িয়ে খুতবা দিচ্ছিলেন এবং সমবেত সাহাবিদের লক্ষ্য করে বললেন: \"তোমরা বসে পড়ো!\" আব্দুল্লাহ ইবনে রাওয়াহা তখনো মসজিদের বাইরে রাস্তায় হাঁটছিলেন। রাসুলের পবিত্র মুখ থেকে \"বসে পড়ো\" শব্দ উচ্চারিত হওয়ামাত্র আব্দুল্লাহ রাস্তায় ধূলিবালির ওপর তৎক্ষণাৎ বসে পড়লেন এবং খুতবা শেষ হওয়া পর্যন্ত সেখানেই বসে রইলেন। সালাত শেষে সাহাবিরা রাসুলকে বিষয়টি জানালে রাসুল (সা.) অত্যন্ত প্রীত হয়ে আব্দুল্লাহর কপালে হাত রেখে দোয়া করলেন: \"আল্লাহ তাঁর ও তাঁর রাসুলের আনুগত্যের প্রতি তোমার আগ্রহ আরও বাড়িয়ে দিন!\""
      }
    ],
