    "summaryBn": "রাসুলুল্লাহ (সা.)-এর আপন প্রিয়তম চাচা, যিনি বয়সে রাসুলের চেয়ে মাত্র তিন বছরের বড় ছিলেন; হুনাইনের সংকটময় মুহূর্তে যাঁর পর্বতসম গম্ভীর কণ্ঠের এক ডাকে হাজার হাজার সাহাবি ময়দানে ফিরে এসেছিলেন।",
    "detailedBiographyBn": "হযরত আব্বাস ইবনে আব্দুল মুত্তালিব (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর আপন পিতৃব্য। জাহেলি যুগে তিনি কাবার হাজিদের পানি পান করানো (সিকায়াহ) ও সুরক্ষার দায়িত্বে নিয়োজিত সম্মানিত কুরাইশ নেতা ছিলেন। রাসুল (সা.)-কে তিনি শৈশব থেকেই অকৃত্রিম ভালোবাসতেন। আকাবার দ্বিতীয় শপথে তিনি তখনও প্রকাশ্যে ইসলাম গ্রহণ করেননি, তবুও ভাতিজা মুহাম্মদের নিরাপত্তার স্বার্থে মদিনাবাসীদের কঠোর প্রতিশ্রুতি আদায় করতে তিনি ব্যক্তিগতভাবে উপস্থিত ছিলেন।\n\nতিনি গোপনে মক্কায় মুসলমানদের স্বার্থরক্ষা ও গোয়েন্দা তথ্য সরবরাহ করতেন। বদর যুদ্ধে অনিচ্ছাসত্ত্বেও কাফেরদের সাথে এসেছিলেন এবং বন্দি হন। পরবর্তীতে নিজের মুক্তিপণ দিয়ে মক্কায় ফিরে যান এবং মক্কা বিজয়ের পূর্বে প্রকাশ্যে মদিনায় হিজরত করেন। রাসুল (সা.) বলতেন: \"আমি যেমন নবিদের মধ্যে শেষ, তেমনি আব্বাস হিজরতকারীদের মধ্যে শেষ!\"\n\n৮ হিজরিতে হুনাইনের যুদ্ধে যখন হাওয়াযিন গোত্রের অতর্কিত তীরের বন্যায় ১২ হাজার মুসলিম সৈন্য ছত্রভঙ্গ হয়ে পিছু হটছিল, রাসুল (সা.) একাকী নিজের খচ্চর হাঁকিয়ে কাফেরদের দিকে এগোচ্ছিলেন। তখন আব্বাস রাসুলের খচ্চরের লাগাম ধরে পাহাড়সম সাহসে দাঁড়িয়ে ছিলেন। রাসুল (সা.) বললেন: \"চাচাজান! আপনার উচ্চকণ্ঠে আনসার ও বাবলা গাছের নিচে বাইয়াতকারীদের ডাকুন!\" আব্বাসের কণ্ঠ ছিল এক মাইল দূর থেকেও স্পষ্ট শোনা যেত এমন মেঘের মতো গম্ভীর। আব্বাস গর্জে উঠলেন: \"হে আনসাররা! হে বাবলা গাছের নিচে বাইয়াতকারী সাহাবিরা! রাসুলুল্লাহ এখানে!\" এই এক ডাকে সাহাবিরা নিজেদের উটের লাগাম ঘুরিয়ে \"লাব্বাইক! লাব্বাইক!\" বলে ময়দানে ফিরে এসে ঐতিহাসিক বিজয় অর্জন করেন। খলিফা উমর (রা.) বৃষ্টির জন্য আব্বাসের উসিলা দিয়ে নামাজ আদায় করতেন।",
    "islamAcceptanceBn": "মক্কায় গোপনে ইসলাম পালন করতেন এবং মক্কা বিজয়ের ঠিক প্রাক্কালে সপরিবারে প্রকাশ্যে মদিনায় হিজরত করেন।",
