    "summaryBn": "উম্মে সুলাইমের স্বামী ও আনাস (রা.)-এর সৎপিতা; ইসলামের ইতিহাসে যাঁর দেনমোহর ছিল ইসলাম গ্রহণ; যিনি মসজিদে নববীর সবচেয়ে সুস্বাদু পানির প্রিয় বাগান ‘বাইরুহা’ অকাতরে দান করেছিলেন এবং উহুদে রাসুলের সামনে বুক পেতে দিয়ে বলেছিলেন: \"আমার বুক আপনার বুকের ঢাল!\"",
    "detailedBiographyBn": "হযরত আবু তালহা যায়েদ ইবনে সাহল আল-আনসারী (রা.) ছিলেন মদিনার বনু নাজ্জার গোত্রের একজন অতি দক্ষ তীরন্দাজ ও ধনী সাহাবি। তিনি উম্মে সুলাইম (রা.)-কে বিবাহের প্রস্তাব দিলে উম্মে সুলাইম বলেছিলেন: \"হে আবু তালহা! আপনি একজন মূর্তিপূজক আর আমি একজন মুসলিম নারী। আপনি যদি ইসলাম গ্রহণ করেন, তবে আপনার সেই ইসলাম গ্রহণই হবে আমার দেনমোহর! স্বর্ণ বা রূপার কোনো মোহর আমার লাগবে না!\" আবু তালহা ইসলাম গ্রহণ করলেন এবং তাঁদের বিবাহ সম্পন্ন হলো, যা ইসলামের ইতিহাসে শ্রেষ্ঠ দেনমোহর হিসেবে গণ্য।\n\nআবু তালহা ছিলেন আরবের অদ্বিতীয় তীরন্দাজ। উহুদের যুদ্ধে কাফেরদের তীরের মুখে যখন সবাই অস্থির, আবু তালহা রাসুল (সা.)-এর সামনে দাঁড়িয়ে নিজের তীরের থলে খুলে একটানা তীর ছুড়ছিলেন। তাঁর তীরে বহু কাফের নিহত হয়। রাসুল (সা.) যখন উঁকি দিয়ে কাফেরদের দেখতে যেতেন, আবু তালহা নিজের বুক দিয়ে রাসুলকে আবৃত করে বলতেন: \"হে আল্লাহর রাসুল! আমার মা-বাবা আপনার ওপর কোরবান হোক, আপনি মাথা উঁচু করবেন না! শত্রুর কোনো তীর যেন আপনার পবিত্র গায়ে না লাগে, আমার বুক আপনার বুকের জন্য ঢাল হোক!\"\n\nযখন কুরআনের আয়াত নাজিল হলো—\"তোমরা কখনোই প্রকৃত পুণ্য লাভ করতে পারবে না যতক্ষণ না তোমাদের প্রিয় বস্তু আল্লাহর রাস্তায় ব্যয় করবে\", তখন আবু তালহা কালবিলম্ব না করে মসজিদে নববীর ঠিক বিপরীতে অবস্থিত তাঁর জীবনের সবচেয়ে মূল্যবান ও সুস্বাদু পানির বাগান ‘বাইরুহা’ সম্পূর্ণ আল্লাহর রাস্তায় ওয়াকফ করে দেন। জীবনের শেষ দিনগুলোতে রোজা রাখা অবস্থায় ভূমধ্যসাগরে নৌ-অভিযানে থাকা অবস্থায় তিনি ইন্তেকাল করেন।",
