    "summaryBn": "মদিনার প্রাজ্ঞ ব্যবসায়ী সাহাবি, যিনি বদর যুদ্ধের পর ইসলাম গ্রহণ করে ব্যবসায়ের বদলে দিনরাত ইবাদত ও ইলমে আত্মনিয়োগ করেছিলেন; যাঁকে বিশ্বনবী (সা.) ‘হাকিমুল উম্মাহ’ উপাধিতে ভূষিত করেছিলেন।",
    "detailedBiographyBn": "হযরত আবু দারদা উয়াইমির ইবনে মালিক আল-আনসারী (রা.) ছিলেন মদিনার অন্যতম শীর্ষ ধনী ব্যবসায়ী। বদর যুদ্ধের পূর্বে তিনি ইসলাম গ্রহণ করেননি। তাঁর ঘরে একটি দামি কাঠের মূর্তি ছিল যার পরম পূজা করতেন তিনি।\n\nএকদিন তাঁর পরম বন্ধু আব্দুল্লাহ ইবনে রাওয়াহা (রা.) আবু দারদার অনুপস্থিতিতে তাঁর ঘরে ঢুকে কুড়াল দিয়ে সেই মূর্তিটি টুকরো টুকরো করে ভেঙে ফেলেন। আবু দারদা বাড়ি ফিরে ভাঙা মূর্তি দেখে ক্ষুব্ধ হলেন, কিন্তু কিছুক্ষণ পরই ভাবলেন: \"এই কাঠের পুতুল যদি নিজেকেই রক্ষা করতে না পারে, তবে সে আমাকে কীভাবে রক্ষা করবে?\" তিনি তৎক্ষণাৎ বন্ধু ইবনে রাওয়াহার হাত ধরে রাসুলুল্লাহ (সা.)-এর দরবারে গিয়ে ইসলাম গ্রহণ করেন।\n\nইসলাম গ্রহণের পর তিনি বলতেন: \"আমি চেয়েছিলাম ব্যবসা এবং ইবাদত একসাথে করব, কিন্তু দেখলাম দুটি একসাথে সম্ভব হচ্ছে না; তাই আমি ব্যবসা ছেড়ে দিয়ে সম্পূর্ণ ইবাদত ও ইলমের জন্য নিজেকে উৎসর্গ করলাম!\" রাসুলুল্লাহ (সা.) সালমান ফারসির সাথে তাঁর ভ্রাতৃত্ব বন্ধন গড়ে দিয়েছিলেন। খলিফা উমর (রা.) তাঁকে সিরিয়ার দামেশকে কুরআন শিক্ষক ও প্রধান বিচারপতি নিয়োগ করেন। দামেশকের উমাইয়া মসজিদে তিনি এক সুবিশাল কুরআন শিক্ষা কেন্দ্র গড়ে তোলেন যেখানে প্রতিদিন ১৬০০-এর বেশি ছাত্র তাঁর কাছে কুরআন শিখত। তিনি বলতেন: \"এক ঘণ্টা চিন্তা-গবেষণা করা সারা রাত নফল সালাত আদায়ের চেয়েও উত্তম!\"",
    "islamAcceptanceBn": "বদর যুদ্ধের পর নিজ ঘরের কাঠের মূর্তির অসহায়ত্ব উপলব্ধি করে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
