        "story": "খলিফা উমর (রা.) একবার শামে এসে গভীর রাতে কোনো প্রহরীর পাহারা ছাড়াই আবু দারদার বাড়িতে প্রবেশ করলেন। উমর অন্ধকারে হাতড়ে দেখলেন দরজায় কোনো খিল নেই, ঘরে কোনো আলো নেই এবং আবু দারদা মাটির ওপর একটি পাতলা কম্বল গায়ে দিয়ে শুয়ে আছেন আর মাথার নিচে একটি পাথর রাখা! উমর (রা.) শিউরে উঠে কেঁদে বললেন: \"হে আবু দারদা! আল্লাহ কি তোমাকে সচ্ছলতা দেননি? তুমি সিরিয়ার প্রধান বিচারপতি, তবে তোমার এই হাল কেন?\" আবু দারদা অন্ধকারে উঠে বললেন: \"হে উমর! আপনার কি রাসুল (সা.)-এর সেই অসিয়তের কথা মনে নেই—দুনিয়াতে তোমাদের সম্বল যেন একজন মুসাফিরের বোঝার মতো হয়?\" উমর (রা.) এই কথা শুনে ঘরের মেঝেতে বসে আবু দারদার সাথে সারারাত অঝোরে কাঁদলেন।"
