    "summaryBn": "ইয়েমেনের আশআর গোত্রের প্রধান সাহাবি, যাঁর মিষ্টি ও হৃদয়গ্রাহী কুরআন তিলাওয়াত শুনে রাসুল (সা.) বলেছিলেন: \"আবু মূসাকে দাউদ (আ.)-এর সুরের একটি অংশ দান করা হয়েছে!\"; যিনি বসরা ও কুফার ন্যায়পরায়ণ গভর্নর ছিলেন।",
    "detailedBiographyBn": "হযরত আবু মূসা আব্দুল্লাহ ইবনে কায়স আল-আশয়ারি (রা.) ছিলেন ইয়েমেনের বিখ্যাত আশআর গোত্রের সন্তান। মক্কায় রাসুলুল্লাহ (সা.)-এর নবুওয়াতের খবর শুনে তিনি সুদূর ইয়েমেন থেকে এসে ইসলাম গ্রহণ করেন। পরবর্তীতে নিজ গোত্রের ৫০ জনের বেশি লোককে নিয়ে একটি জাহাজে চড়ে মদিনার উদ্দেশ্যে রওনা হলে সমুদ্রের ঝড়ে পথভ্রষ্ট হয়ে হাবশায় জাফর (রা.)-এর কাফেলার সাথে মিলিত হন এবং ৭ হিজরিতে খায়বারের সময় মদিনায় পৌঁছেন।\n\nআবু মূসা (রা.) ছিলেন কুরআনের এমন এক জাদুকরী ক্বারী যাঁর তিলাওয়াত শুনলে পাষাণ হৃদয়ও গলে যেত। একদিন রাসুলুল্লাহ (সা.) রাতের আঁধারে আয়েশা (রা.)-কে নিয়ে দাঁড়িয়ে আবু মূসার তিলাওয়াত দীর্ঘক্ষণ শুনলেন। পরদিন রাসুল তাঁকে বললেন: \"হে আবু মূসা! কাল রাতে যদি তুমি দেখতে আমি কেমন মনোযোগ দিয়ে তোমার তিলাওয়াত শুনছিলাম! তোমাকে দাউদ (আ.)-এর সুরের বাঁশি দান করা হয়েছে!\" আবু মূসা আবেগে বললেন: \"হে আল্লাহর রাসুল! আমি যদি জানতাম আপনি শুনছেন, তবে আমি আরও বেশি সুন্দর করে তিলাওয়াত করতাম!\"\n\nতিনি ছিলেন অসাধারণ ফকিহ ও বীর যোদ্ধা। খলিফা উমর (রা.) তাঁকে বসরার গভর্নর নিযুক্ত করেন। তিনি আহওয়ায ও পারস্যের তুসতার দুর্গ বিজয়ে অগ্রণী ভূমিকা পালন করেন। সিফফিনের যুদ্ধের পর ঐতিহাসিক তাহকিম (সালিসি)-এ আলী (রা.)-এর পক্ষ থেকে প্রধান সালিস নিযুক্ত হয়েছিলেন।",
