    "birthAndDeathBn": "জন্ম: গিফার গোত্র | ওফাত: ৩২ হিজরি রাবাযাহ মরুভূমি (একাকী)",
    "summaryBn": "আরবের কুখ্যাত ডাকাত গিফার গোত্র থেকে এসে মক্কার কাবার চত্বরে একা দাঁড়িয়ে সর্বপ্রথম প্রকাশ্যে কালিমার হুংকার দেওয়া নির্ভীক সাহাবি; যাঁর সততা সম্পর্কে রাসুল (সা.) বলেছিলেন: \"নীল আকাশের নিচে আবু যারের চেয়ে বেশি সত্যবাদী মানুষ আর কেউ হাঁটেনি!\"",
    "detailedBiographyBn": "হযরত আবু যার জুনদুব ইবনে জুনাদাহ আল-গিফারী (রা.) ছিলেন লোহিত সাগরের উপকূলের কাফেলা লুণ্ঠনকারী কুখ্যাত বনু গিফার গোত্রের মানুষ। কিন্তু জাহেলি যুগেও তিনি মূর্তিপূজা ঘৃণা করতেন এবং একত্ববাদে বিশ্বাসী হয়ে একাকী সালাত পড়তেন। রাসুলুল্লাহ (সা.)-এর নবুওয়াতের কথা শুনে তিনি মক্কায় এসে চতুর্থ বা পঞ্চম ব্যক্তি হিসেবে ইসলাম গ্রহণ করেন।\n\nরাসুল (সা.) তাঁকে বললেন: \"আবু যার! তোমার ইসলাম গোপন রাখো এবং গোত্রে ফিরে যাও!\" কিন্তু নির্ভীক আবু যার বললেন: \"সেই সত্তার শপথ যাঁর হাতে আমার প্রাণ! আমি কাবার চত্বরে কাফেরদের জমায়েতে দাঁড়িয়ে প্রকাশ্যে চিৎকার করে কালিমার ঘোষণা দেব!\" তিনি কাবার সামনে দাঁড়িয়ে চিৎকার করে বললেন: \"আশহাদু আল-লা ইলাহা ইল্লাল্লাহু ওয়া আশহাদু আন্না মুহাম্মাদার রাসুলুল্লাহ!\" কাফেররা তাঁর ওপর ঝাঁপিয়ে পড়ে বেধড়ক মারতে মারতে তাঁকে রক্তাক্ত ও অজ্ঞান করে ফেলল। আব্বাস (রা.) এসে তাঁকে রক্ষা করলেন।\n\nআবু যার ছিলেন চরম অনাড়ম্বর ও দুনিয়াবিমুখতার জীবন্ত প্রতীক। তিনি প্রয়োজনের অতিরিক্ত একটি দিরহামও নিজের কাছে রাখতেন না, সাথে সাথে গরিবদের মাঝে বিলিয়ে দিতেন। ধনীদের অতিরিক্ত সম্পদ পুঞ্জীভূত করার বিরুদ্ধে তিনি কঠোর অবস্থান নিতেন। রাসুল (সা.) বহু পূর্বেই ভবিষ্যদ্বাণী করেছিলেন: \"আবু যার একাকী চলবে, একাকী মৃত্যুবরণ করবে এবং কেয়ামতের দিন একাকী পুনরুত্থিত হবে!\" পরবর্তীতে ৩২ হিজরিতে মদিনার নির্জন রাবাযাহ প্রান্তরে একাকী একটি তাঁবুতে তিনি ইন্তেকাল করেন।",
    "islamAcceptanceBn": "ইসলামের একেবারেই সূচনালগ্নে পঞ্চম ব্যক্তি হিসেবে ইসলাম গ্রহণ করেন এবং কাবার চত্বরে প্রকাশ্যে তাওহীদের হুংকার তোলেন।",
