        "story": "৩২ হিজরিতে মদিনার বাইরে নির্জন রাবাযাহ মরুভূমিতে আবু যার (রা.) মৃত্যুশয্যায় শুয়ে আছেন। পাশে কেবল তাঁর বৃদ্ধা স্ত্রী ও একটি কন্যা। স্ত্রী কাঁদছিলেন কারণ কাফন দেওয়ার মতো কোনো কাপড় ঘরে ছিল না। আবু যার মুচকি হেসে বললেন: \"কেঁদো না! রাসুলুল্লাহ (সা.) একদিন আমাদের কয়েকজনকে বলেছিলেন—তোমাদের একজন নির্জন প্রান্তরে মারা যাবে এবং একদল মুমিন ব্যক্তি এসে তার কাফন-দাফন করবে! সেই দলের বাকি সবাই শহরে মারা গেছে, কেবল আমি বাকি। রাস্তায় গিয়ে তাকাও, মুমিনদের কাফেলা এখনই আসছে!\" কিছুক্ষণ পরই কুফা থেকে আব্দুল্লাহ ইবনে মাসউদ (রা.)-এর নেতৃত্বে একটি কাফেলা এসে হাজির হলো। তাঁবুতে আবু যারকে মৃত দেখে ইবনে মাসউদ অঝোরে কাঁদতে লাগলেন এবং রাসুলের সেই বাণী স্মরণ করলেন: \"রহমাতুল্লাহি আলা আবি যার! সে একাকী চলে, একাকী মরবে এবং একাকী উঠবে!\""
