    "detailedBiographyBn": "হযরত আবু কাতাদাহ আল-হারিস ইবনে রিবয়ী আল-আনসারী (রা.) ছিলেন মদিনার খাযরাজ গোত্রের এক অত্যন্ত সাহসী অশ্বারোহী যোদ্ধা। উহুদ যুদ্ধের পর থেকে তিনি রাসুলুল্লাহ (সা.)-এর প্রতিটি অভিযানে বীরত্ব প্রদর্শন করেন।\n\n৬ হিজরিতে উয়াইনা ইবনে হিসনের নেতৃত্বে একদল ডাকাত মদিনার চারণভূমিতে আক্রমণ করে রাসুলুল্লাহ (সা.)-এর দুধের উটগুলো লুট করে এবং রাখালকে হত্যা করে। এই খবর পাওয়া মাত্র আবু কাতাদাহ এবং সালামা ইবনুল আকওয়া ডাকাতদের পিছু ধাওয়া করেন। আবু কাতাদাহ অশ্বারোহী হিসেবে একাই ডাকাত দলের প্রধান হাবিব ইবনে উয়ায়নাকে বর্শার আঘাতে হত্যা করেন এবং সমস্ত উট ছিনিয়ে আনেন। রাসুলুল্লাহ (সা.) অত্যন্ত আনন্দিত হয়ে ঘোষণা দেন: \"আজ আমাদের শ্রেষ্ঠ অশ্বারোহী হলো আবু কাতাদাহ, আর আমাদের শ্রেষ্ঠ পদাতিক হলো সালামা ইবনুল আকওয়া!\"\n\nতিনি রাসুল (সা.)-এর অত্যন্ত বিশ্বস্ত দেহরক্ষী ছিলেন। একবার রাতের সফরে রাসুল (সা.) উটের পিঠে ক্লান্তিতে ঘুমিয়ে একপাশে হেলে পড়ছিলেন, আবু কাতাদাহ সারা রাত না ঘুমিয়ে নিজের ঘোড়া দিয়ে রাসুলের পাশে পাশে গিয়ে রাসুলকে পড়ে যাওয়া থেকে রক্ষা করেন। ভোরবেলা রাসুল (সা.) জাগ্রত হয়ে এই দৃশ্য দেখে হাত তুলে দোয়া করেছিলেন: \"আবু কাতাদাহ! তুমি যেভাবে আল্লাহর রাসুলকে রক্ষা করেছ, আল্লাহ যেন তেমনি তোমাকে দুনিয়া ও আখিরাতে হেফাজত করেন!\" তাঁর চেহারা ৭০ বছর বয়সেও ১৫ বছরের তরুণের মতো সতেজ ও উজ্জ্বল ছিল।",
