    "summaryBn": "রাসুলুল্লাহ (সা.)-এর আপন ফুফু বাররাহ বিনতে আব্দুল মুত্তালিবের পুত্র এবং সুয়াইবা দাসীর দুধপানের কারণে রাসুলের দুধভাই; ইসলামের ইতিহাসে সর্বপ্রথম হিজরতকারী সাহাবি, যাঁর ওফাতের সময় রাসুল স্বয়ং তাঁর চোখ বন্ধ করে দিয়েছিলেন।",
    "detailedBiographyBn": "হযরত আবু সালামা আব্দুল্লাহ ইবনে আব্দিল আসাদ (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর অতি আপনজন। তিনি একাধারে রাসুলের ফুফাতো ভাই এবং দুধভাই ছিলেন। দারুল আরকামে যাওয়ার পূর্বেই তিনি তাঁর স্ত্রী উম্মে সালামা (রা.)-সহ ইসলামের সূচনাতেই ঈমান আনেন।\n\nমক্কার নির্মম নির্যাতন সহ্য করে তিনি তাঁর স্ত্রীকে নিয়ে আবিসিনিয়ায় প্রথম হিজরতকারীদের অন্তর্ভুক্ত ছিলেন। পরবর্তীতে মক্কায় ফিরে মদিনায় হিজরতের নির্দেশ এলে তিনিই ছিলেন সর্বপ্রথম ব্যক্তি যিনি মদিনার উদ্দেশ্যে হিজরত শুরু করেন। কিন্তু মক্কার মুশরিকরা তাঁর স্ত্রীকে ছিনিয়ে নিয়ে বন্দি করে এবং শিশু সন্তান সালামার হাত টেনে ছিঁড়ে ফেলে নিয়ে যায়। আবু সালামা একাকী ছিন্নভিন্ন হৃদয়ে মদিনায় পৌঁছান। এক বছর পর আল্লাহ তাঁর পরিবারকে মদিনায় একত্রিত করেন।\n\nবদর যুদ্ধে তিনি বীরবিক্রমে লড়াই করেন। ৩ হিজরির উহুদ যুদ্ধে কাফেরদের একটি বিষাক্ত তীরের আঘাতে তাঁর বাহুতে গভীর ক্ষত তৈরি হয়। দীর্ঘ এক মাস চিকিৎসার পর তিনি আপাতদৃষ্টিতে সুস্থ হন। কিন্তু ৪ হিজরির জুমাদাল উলা মাসে সেই ক্ষতের মুখ পুনরায় ফেটে গিয়ে ইনফেকশন ছড়িয়ে পড়ে এবং তিনি মৃত্যুশয্যায় পতিত হন। রাসুলুল্লাহ (সা.) তাঁর শয্যাপাশে এসে বসেন। আবু সালামা শেষ নিঃশ্বাস ত্যাগ করলে রাসুল (সা.) নিজ হাতে তাঁর উন্মুক্ত চোখ দুটি পরম মমতায় বন্ধ করে দেন এবং তাঁর জানাজায় নয়টি তাকবির দিয়ে সালাত আদায় করেন।",
    "islamAcceptanceBn": "আরকাম (রা.)-এর ঘরে যাওয়ার আগেই ইসলামের প্রারম্ভিক দশজনের অন্যতম হয়ে ইসলাম গ্রহণ করেন।",
