        "story": "উম্মে সালামা (রা.) বলেন: আবু সালামার মৃত্যুর মুহূর্তে রাসুলুল্লাহ (সা.) ঘরে প্রবেশ করলেন। আবু সালামার চোখ দুটি স্থির হয়ে আকাশের দিকে তাকিয়ে ছিল। রাসুল (সা.) পরম মমতায় নিজের হাত দিয়ে তাঁর চোখের পাতা দুটি বন্ধ করে দিলেন। এরপর রাসুল বললেন: \"নিশ্চয়ই যখন রুহ কবজ করা হয়, তখন দৃষ্টি তার পিছু নেয়।\" এ কথা শুনে ঘরের মহিলারা কান্নায় ভেঙে পড়ল। রাসুল (সা.) বললেন: \"তোমরা নিজেদের জন্য কেবল কল্যাণের দোয়াই করো, কারণ তোমরা যা-ই বলবে ফেরেশতারা তার ওপর আমিন বলবে!\" এরপর রাসুল দুহাত তুলে দোয়া করলেন: \"হে আল্লাহ! আবু সালামাকে ক্ষমা করুন, হেদায়াতপ্রাপ্তদের মাঝে তাঁর মর্যাদা সুউচ্চ করুন এবং তাঁর কবরকে প্রশস্ত ও নূর দিয়ে আলোকিত করে দিন!\""
