    "summaryBn": "মদিনার আনসার যুবক, যিনি রাতের আঁধারে সালাতরত অবস্থায় শরীরে তিনটি তীর বিঁধে রক্তে ভিজে গেলেও সূরা কাহাফের তিলাওয়াত শেষ না করে সালাত ভাঙেননি; এবং যাঁর লাঠির মাথায় অন্ধকার রাতে প্রদীপের মতো আলো জ্বলত।",
    "detailedBiographyBn": "হযরত আব্বাদ ইবনে বিশর (রা.) ছিলেন মদিনার আওস গোত্রের এক পরম রূপবান, সুকণ্ঠী ও নির্ভীক তরুণ সাহাবি। মুসআব ইবনে উমাইরের মুখে কুরআন শুনে তিনি মাত্র ২৫ বছর বয়সে ইসলাম গ্রহণ করেন। কুরআনের প্রতি তাঁর এমন গভীর ভালোবাসা ছিল যে সাহাবিরা তাঁকে ‘ইমামুল কুরআন’ বলতেন।\n\nএকবার জাতুর রিকা অভিযানে রাসুলুল্লাহ (সা.) রাতে এক পাহাড়ি গিরিপথ পাহারা দেওয়ার জন্য আব্বাদ ইবনে বিশর ও আম্মার ইবনে ইয়াসিরকে দায়িত্ব দিলেন। তাঁরা পালা করে পাহারা দেওয়ার সিদ্ধান্ত নিলেন। প্রথমার্ধে আব্বাদ পাহারা দিচ্ছিলেন। তিনি সময় নষ্ট না করে পাহারা দেওয়ার পাশাপাশি দাঁড়িয়ে নফল সালাত শুরু করলেন এবং সূরা কাহাফ তিলাওয়াত করতে লাগলেন। এমন সময় এক কাফের শত্রু এসে তাঁকে লক্ষ্য করে একটি তীর ছুড়ল। তীরটি আব্বাদের শরীরে বিঁধে রক্ত ঝরতে লাগল। আব্বাদ তীরটি শরীর থেকে টেনে খুলে ফেলে সালাত অব্যাহত রাখলেন। শত্রুটি দ্বিতীয় তীর ছুড়ল, আব্বাদ সেটিও খুলে ফেলে দিলেন। শত্রুটি তৃতীয় তীর ছুড়ল। শরীর থেকে রক্তের ফোয়ারা বইতে থাকা সত্ত্বেও আব্বাদ তিলাওয়াত শেষ করে রুকু ও সিজদা সম্পন্ন করলেন। এরপর তিনি আম্মারকে ডেকে বললেন: \"আম্মার ওঠো! আমি মারাত্মক আহত হয়েছি!\" আম্মার উঠে রক্তের বন্যা দেখে আঁতকে উঠে বললেন: \"সুবহানাল্লাহ! প্রথম তীর লাগার পরই তুমি আমাকে ডাকলে না কেন?\" আব্বাদ শান্ত কণ্ঠে বললেন: \"আমি সালাতে এমন এক মধুর সূরা (সূরা কাহাফ) পড়ছিলাম যে তা শেষ না করে সালাত ভাঙতে আমার মন চাইছিল না! আল্লাহর কসম, রাসুলুল্লাহ (সা.) যে গিরিপথ পাহারার দায়িত্ব আমার ওপর দিয়েছিলেন তা নষ্ট হওয়ার ভয় না থাকলে আমার শরীর থেকে প্রাণ বের হয়ে গেলেও আমি সালাত ভাঙতাম না!\"\n\n১২ হিজরিতে ইয়ামামার যুদ্ধে তিনি আনসারদের পতাকা নিয়ে মুসায়লামার বিরুদ্ধে বীরদর্পে লড়াই করে শাহাদাত বরণ করেন।",
    "islamAcceptanceBn": "মুসআব ইবনে উমাইরের কাছে মদিনায় হিজরতের পূর্বেই ইসলাম গ্রহণ করেন।",
