    "birthAndDeathBn": "জন্ম: মক্কা (নবুওয়াতের ৪র্থ বর্ষ) | ওফাত: ৫৪ হিজরি মদিনা (৬০ বছর)",
    "summaryBn": "যায়েদ বিন হারেসা ও উম্মে আইমানের পুত্র; রাসুলুল্লাহ (সা.) যাঁর কপালে চুম্বন করে নাতি হাসানের মতো নিজের কোলে বসাতেন; এবং যিনি মাত্র ১৭-১৮ বছর বয়সে রোমানদের বিরুদ্ধে সুবিশাল অভিযানের সর্বাধিনায়ক নিযুক্ত হয়েছিলেন।",
    "detailedBiographyBn": "হযরত উসামা ইবনে যায়েদ (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর অত্যন্ত আদরের সাহাবি। তাঁর পিতা যায়েদ ছিলেন রাসুলের দত্তক পুত্র এবং মাতা উম্মে আইমান ছিলেন রাসুলের শৈশবের পালিকামাতা। রাসুল (সা.) এক হাঁটুতে হাসানকে এবং অন্য হাঁটুতে উসামাকে বসিয়ে দুজনকে একসাথে জড়িয়ে ধরে দোয়া করতেন: \"হে আল্লাহ! আমি এদের দুজনকে ভালোবাসি, আপনিও এদের ভালোবাসুন!\"\n\nউসামা ছিলেন শ্যামবর্ণের, কিন্তু তাঁর অন্তরের তেজ ছিল অসাধারণ। বদর ও উহুদে বয়সের কারণে অংশ নিতে পারেননি। খন্দক ও হুনাইনে বীরত্ব দেখান। হুনাইনের যুদ্ধে যখন সবাই ছত্রভঙ্গ হয়েছিল, উসামা রাসুলের পাশে দাঁড়িয়ে থাকা অল্প কয়েকজন বীরের অন্যতম ছিলেন।\n\n১১ হিজরির সফর মাসে রাসুলুল্লাহ (সা.) তাঁর ওফাতের ঠিক কয়েকদিন পূর্বে রোমান সাম্রাজ্যের বিরুদ্ধে শামে এক বড় অভিযানের সিদ্ধান্ত নেন এবং মাত্র ১৭ বা ১৮ বছরের তরুণ উসামাকে সেই বাহিনীর সর্বাধিনায়ক নিযুক্ত করেন। এই বাহিনীতে আবু বকর, উমর, আবু উবাইদা ও সা’দ (রা.)-এর মতো ইসলামের শীর্ষ স্তম্ভ সাহাবিরা সাধারণ সৈন্য ছিলেন! কিছু সাহাবি তাঁর বয়স নিয়ে মৃদু কথা বললে রাসুল (সা.) অসুস্থ শরীরে মাথায় পট্টি বেঁধে মিম্বারে উঠে কসম খেয়ে বলেন: \"তোমরা যদি আজ উসামার সেনাপতিত্ব নিয়ে কথা বলো, তবে ইতিপূর্বে তার পিতার সেনাপতিত্ব নিয়েও তোমরা কথা বলেছিলে! আল্লাহর কসম, সে সেনাপতিত্বের পূর্ণ যোগ্য এবং আমার কাছে সবচেয়ে প্রিয় মানুষদের একজন!\" রাসুলের ওফাতের পর খলিফা আবু বকর (রা.) খালি পায়ে হেঁটে ঘোড়ায় চড়া উসামার সাথে মদিনার বাইরে পর্যন্ত গিয়ে তাঁকে বিদায় জানান। উসামা বিজয়ী হয়ে বিপুল গনিমত নিয়ে মদিনায় ফেরেন।",
