        "story": "উসামা (রা.) বর্ণনা করেন: রাসুলুল্লাহ (সা.)-এর অন্তিম রোগশয্যায় আমি জুন্দ থেকে মদিনায় ফিরে রাসুলের ঘরে ঢুকলাম। রাসুল তখন প্রচণ্ড জ্বরে কথা বলতে পারছিলেন না। তিনি চোখ মেলে আমার দিকে তাকালেন। এরপর তিনি নিজের হাত দুটি আকাশের দিকে তুললেন এবং পরম স্নেহে আমার মাথার ওপর রাখলেন। আমি বুঝতে পারলাম তিনি মুখে কোনো কথা বলতে না পারলেও আল্লাহর দরবারে আমার জন্য হাত তুলে দোয়া করছেন! এটাই ছিল রাসুলের সাথে আমার শেষ বিদায়।"
