    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ৩৬ হিজরি মাদায়েন (পারস্য)",
    "summaryBn": "রাসুলুল্লাহ (সা.)-এর সবচেয়ে বিশ্বস্ত গোপন সহকারী, যাঁর কাছে রাসুল (সা.) মদিনার সমস্ত মুনাফিকদের গোপন নাম প্রকাশ করেছিলেন; এবং যিনি খন্দকের কনকনে বরফশীতল রাতে একা শত্রুশিবিরে ঢুকে আবু সুফিয়ানের তাঁবুর খবর এনেছিলেন।",
    "detailedBiographyBn": "হযরত হুজায়ফা ইবনুল ইয়ামান (রা.) ছিলেন বনু আবস গোত্রের সন্তান। পিতা মক্কার অধিবাসী হলেও রক্তক্ষয়ী বিবাদের কারণে মদিনায় বসবাস করায় হুজায়ফা একাধারে মুহাজির ও আনসার উভয় মর্যাদার অধিকারী হন। উহুদ যুদ্ধে এক মর্মান্তিক ভুল বোঝাবুঝির কারণে মুসলিম সৈন্যরা না চিনে হুজায়ফার পিতা ইয়ামানকে কাফের ভেবে হত্যা করে ফেলে। হুজায়ফা চিৎকার করে বলেছিলেন: \"উনি আমার পিতা!\" কিন্তু ততক্ষণে দেরি হয়ে যায়। হুজায়ফা কোনো প্রতিশোধ না নিয়ে বলেছিলেন: \"আল্লাহ তোমাদের ক্ষমা করুন, তিনি পরম দয়ালু!\" রাসুল (সা.) রক্তের দিয়াত দিতে চাইলে হুজায়ফা তা মুসলিমদের বায়তুল মালে দান করে দেন।\n\nহুজায়ফা ছিলেন রাসুলুল্লাহ (সা.)-এর ‘সাহিবুস সিরর’ বা গোপন তথ্যের আমানতদার। রাসুল (সা.) মদিনার মুনাফিকদের সমস্ত নাম ও পরিচয় হুজায়ফাকে গোপনে তালিকা আকারে জানিয়েছিলেন যা অন্য কোনো সাহাবি এমনকি আবু বকর বা উমরও জানতেন না! খলিফা উমর (রা.) কোনো ব্যক্তির জানাজায় যাওয়ার আগে দেখতেন হুজায়ফা জানাজায় এসেছেন কি না। হুজায়ফা না এলে উমর বুঝতেন লোকটি মুনাফিক এবং উমরও জানাজা পড়তেন না।\n\nখন্দক যুদ্ধের রাতে যখন হাড় কাঁপানো তীব্র শীত ও সাইক্লোন ঝড় বইছিল, রাসুল (সা.) হুজায়ফাকে একা কাফেরদের শিবিরে গিয়ে তথ্য আনার নির্দেশ দেন। হুজায়ফা নিঃশব্দে আবু সুফিয়ানের তাঁবুর একদম পাশে বসে আগুন পোহান এবং শত্রুর পলায়নের তথ্য নিয়ে ফিরে আসেন। নাহাওয়ান্দ যুদ্ধে সেনাপতি নু’মান শহীদ হওয়ার পর হুজায়ফা পতাকা হাতে নিয়ে পারস্য বাহিনীকে চূড়ান্তভাবে পরাজিত করে মাদায়েন জয় করেন।",
    "islamAcceptanceBn": "মদিনায় রাসুল (সা.)-এর হিজরতের পূর্বেই পিতার সাথে ইসলাম গ্রহণ করেন।",
