        "story": "আমিরুল মুমিনীন উমর ফারুক (রা.) একবার একান্তে হুজায়ফাকে ডেকে হাত ধরে কেঁদে ফেললেন। উমর বললেন: \"হে হুজায়ফা! আমি তোমাকে আল্লাহর নামে কসম দিয়ে জিজ্ঞাসা করছি, রাসুলুল্লাহ (সা.) মুনাফিকদের যে তালিকা তোমাকে দিয়েছিলেন, তার মধ্যে কি কোথাও এই অভাগা উমরের নাম রয়েছে?\" হুজায়ফা শিউরে উঠে কেঁদে ফেলে বললেন: \"আল্লাহর কসম হে আমিরুল মুমিনীন! আপনার নাম সেখানে নেই! এবং আপনার পর আমি আর কাউকে এই ব্যাপারে কোনোদিন নিশ্চয়তা দেব না!\""
