    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ৭৪ হিজরি মদিনা (৮৬ বছর)",
    "summaryBn": "উহুদ যুদ্ধে মাত্র ১৫ বছর বয়সে পায়ের আঙুলে ভর দিয়ে নিজেকে লম্বা দেখিয়ে যুদ্ধে যাওয়ার অনুমতি পাওয়া কিশোর সাহাবি; যাঁর বুকে বিঁধা তীরের ফলা রাসুল (সা.) নিজ হাতে কেটে রেখে বলেছিলেন: \"কেয়ামতের দিন আমি তোমার এই ক্ষতের সাক্ষী হব!\"",
    "detailedBiographyBn": "হযরত রাফে ইবনে খাদিজ (রা.) ছিলেন মদিনার আওস গোত্রের সন্তান। বদর যুদ্ধের সময় তিনি ছিলেন একেবারেই অপ্রাপ্তবয়স্ক বালক। উহুদ যুদ্ধের পূর্বে রাসুলুল্লাহ (সা.) যখন সৈন্যদের পর্যালোচনা করছিলেন, তখন তিনি কম বয়সী ছেলেদের মদিনায় ফেরত পাঠাচ্ছিলেন। রাফে ইবনে খাদিজের বয়স ছিল মাত্র ১৪-১৫ বছর। কিন্তু তিনি তীরন্দাজিতে ছিলেন অত্যন্ত পারদর্শী।\n\nরাফে রাসুল (সা.)-এর সামনে এসে পায়ের আঙুলের ওপর ভর দিয়ে নিজেকে যতটা সম্ভব লম্বা করে দাঁড়িয়ে বুক চিতিয়ে বললেন: \"হে আল্লাহর রাসুল! আমি অত্যন্ত দক্ষ তীরন্দাজ, আমাকে ময়দানে যাওয়ার অনুমতি দিন!\" রাসুল (সা.) তাঁর এই অদম্য আগ্রহ ও পায়ের আঙুলে দাঁড়ানোর ভঙ্গি দেখে মুচকি হাসলেন এবং তাঁকে যুদ্ধে যাওয়ার অনুমতি দিলেন।\n\nউহুদের রক্তক্ষয়ী ময়দানে কিশোর রাফে অসীম সাহসের সাথে লড়াই করেন। যুদ্ধের এক পর্যায়ে কাফেরদের একটি বিষাক্ত তীর তাঁর বুকে বা পাঁজরে এসে বিঁধে যায়। যুদ্ধ শেষে রাসুলুল্লাহ (সা.) নিজে সেই তীরটি বের করতে চাইলেন। তীরের লোহার ফলাটি হাড়ের সাথে এমনভাবে আটকে গিয়েছিল যে তা টানলে হাড় ভেঙে যেতে পারত। রাসুল (সা.) তীরের পেছনের অংশটি কেটে বের করলেন কিন্তু লোহার ফলাটি তাঁর শরীরের ভেতরেই রয়ে গেল। রাসুল (সা.) স্নেহের হাত বুলিয়ে বললেন: \"হে রাফে! এই তীরের ফলাটি তোমার শরীরের ভেতর থাকবে, আর কেয়ামতের ময়দানে আমি স্বয়ং আল্লাহর দরবারে সাক্ষ্য দেব যে তুমি আমার সাথে আল্লাহর রাস্তায় জিহাদ করেছিলে!\" তিনি দীর্ঘ ৮৬ বছর বেঁচে ছিলেন এবং বৃদ্ধ বয়সে সেই ক্ষতের ইনফেকশন থেকেই তিনি শাহাদাতের মর্যাদা লাভ করেন।",
    "islamAcceptanceBn": "মদিনায় বাল্যকালেই পিতামাতার সাথে ইসলাম গ্রহণ করেন এবং রাসুলের সান্নিধ্যে বড় হন।",
