        "story": "উহুদের ময়দানে যখন রাসুল (সা.) রাফের শরীর থেকে তীর কাটছিলেন, রাফে ব্যথায় কাতরাচ্ছিলেন। রাসুল (সা.) তাঁর কপালে নিজের হাত মোবারক রেখে বললেন: \"ধৈর্য ধরো রাফে! আমি চাইলে এটি টেনে বের করতে পারি, তবে হাড়ের ক্ষতি হতে পারে। আর যদি তুমি এটি শরীরের ভেতর রেখে দাও, তবে কেয়ামতের দিন রক্ত ঝরা অবস্থায় এই ক্ষত নিয়ে তুমি উঠবে এবং আমি সাক্ষ্য দেব তুমি শহীদ!\" রাফে ব্যথার মাঝেও হেসে বললেন: \"হে আল্লাহর রাসুল! তবে এই ফলা আমার শরীরেই থেকে যাক, আমি রাসুলের সাক্ষ্য নিয়ে জান্নাতে যেতে চাই!\""
