    "summaryBn": "উহুদ যুদ্ধে কিশোর রাফেকে অনুমতি দিতে দেখে রাসুল (সা.)-এর সামনে এসে কুস্তি লড়ে রাফেকে মাটিতে ফেলে দিয়ে ময়দানে যাওয়ার অনুমতি অর্জনকারী কিশোর বীর; যিনি পরবর্তীতে বসরা ও কুফার দায়িত্ব পালন করেন।",
    "detailedBiographyBn": "হযরত সামুরা ইবনে জুনদুব আল-ফাজারী (রা.) ছিলেন এক অসীম সাহসী তরুণ সাহাবি। উহুদ যুদ্ধের পূর্বে যখন রাসুলুল্লাহ (সা.) রাফে ইবনে খাদিজকে তাঁর তীরন্দাজির দক্ষতার কারণে যুদ্ধে যাওয়ার অনুমতি দিলেন কিন্তু সামুরাকে কম বয়সের কারণে ফিরিয়ে দিলেন, তখন সামুরা রাসুলের সামনে এসে কান্নাজড়িত কণ্ঠে বললেন: \"হে আল্লাহর রাসুল! আপনি রাফেকে অনুমতি দিলেন আর আমাকে ফিরিয়ে দিলেন? অথচ আমি কুস্তিতে রাফেকে মাটিতে আছাড় মেরে ফেলতে পারি!\"\n\nরাসুলুল্লাহ (সা.) মুচকি হেসে বললেন: \"তাই নাকি? তবে তোমরা দুজনের কুস্তি লড়ো!\" সমস্ত সাহাবিদের সামনে দুই কিশোরের কুস্তি হলো। সামুরা সত্যি সত্যিই রাফেকে মাটিতে ফেলে দিলেন। রাসুল (সা.) তাঁর সাহস ও দৈহিক শক্তি দেখে অত্যন্ত আনন্দিত হয়ে সামুরাকেও উহুদের যুদ্ধে অংশগ্রহণের অনুমতি দিলেন।\n\nতিনি খন্দকসহ পরবর্তী সমস্ত যুদ্ধে অংশ নেন। তিনি ছিলেন প্রখর স্মৃতিশক্তির অধিকারী এবং রাসুল (সা.)-এর বহু গুরুত্বপূর্ণ হাদিস ও ফিকহি বিধান বর্ণনা করেছেন। রাসুল (সা.) একবার সাহাবিদের বলেছিলেন: \"তোমাদের মধ্যে যে সবার শেষে মারা যাবে, সে আগুনে পুড়ে বা গরম পানির কষ্টে মারা যাবে।\" সামুরা জীবনের শেষ ভাগে এই হাদিস মনে করে অত্যন্ত ভয়ে থাকতেন এবং শেষ পর্যন্ত তিনি গরম পানির পাত্রে অসাবধানতাবশত পড়ে গিয়ে মারাত্মকভাবে দগ্ধ হয়ে ইন্তেকাল করেন।",
