    "summaryBn": "আরবের ইতিহাসের সবচেয়ে দ্রুতগামী দৌড়বিদ সাহাবি, যিনি খালি পায়ে দৌড়ে বুনো হরিণ ও ঘোড়াকেও ধরে ফেলতে পারতেন; যিনি একাই জি ক্বারাদ অভিযানে ডাকাত দলকে পাথর ও তীর ছুড়ে নাস্তানাবুদ করে সমস্ত গনিমত উদ্ধার করেছিলেন।",
    "detailedBiographyBn": "হযরত সালামা ইবনুল আকওয়া (রা.) ছিলেন আরবের এক অনন্য পদাতিক দৌড়বিদ ও তীরন্দাজ। হুদায়বিয়ার সন্ধির সময় তিনি রাসুলুল্লাহ (সা.)-এর হাতে একবার নয়, পরপর তিনবার—শুরুতে, মাঝে ও শেষে—মৃত্যুর শপথের বাইয়াত গ্রহণ করেছিলেন।\n\n৬ হিজরিতে জি ক্বারাদ অভিযানে যখন কাফেররা রাসুল (সা.)-এর উটের পাল লুট করে পালাচ্ছিল, সালামা একাই পায়ে হেঁটে তাদের পিছু ধাওয়া করেন। আরবের কোনো ঘোড়সওয়ার তাঁর চেয়ে দ্রুত দৌড়াতে পারত না। তিনি পাহাড়ে চড়ে একের পর এক তীর ও পাথর ছুড়ে ডাকাতদের ক্ষতবিক্ষত করতে লাগলেন। যখনই কোনো ঘোড়সওয়ার তাঁর দিকে ফিরত, সালামা নিমেষেই পাহাড়ে উঠে অদৃশ্য হয়ে যেতেন। ডাকাতরা এতটাই অতিষ্ঠ হলো যে তারা নিজেদের প্রাণ বাঁচাতে উটগুলো তো বটেই, এমনকি নিজেদের ত্রিশটিরও বেশি বর্শা ও ভারী চাদর ফেলে রেখে পালাল। সালামা একাই সেই সমস্ত জিনিস সংগ্রহ করে রাসুলের সামনে হাজির করলেন। রাসুল (সা.) হেসে বলেছিলেন: \"আজ আমাদের শ্রেষ্ঠ পদাতিক হলো সালামা!\"\n\nখায়বার যুদ্ধে তাঁর ভাই আমের ইবনে আকওয়া বীরবিক্রমে যুদ্ধ করে শহীদ হন। সালামা ছিলেন চরম দানশীল ও অতিথিপরায়ণ। জীবনের শেষ ভাগে মদিনার রাজনৈতিক সংঘাত এড়াতে তিনি মরুভূমির রাবাযাহ প্রান্তরে নির্জন জীবন বেছে নেন এবং মৃত্যুর পূর্বে মদিনায় ফিরে এসে জান্নাতুল বাকিতে সমাহিত হন।",
    "islamAcceptanceBn": "হুদায়বিয়ার পূর্বেই ইসলাম গ্রহণ করেন এবং গাছের নিচে বাইয়াতে রিদওয়ানে তিনবার বাইয়াত হন।",
