    "categoryKey": "commanders",
    "categoryBn": "রণাঙ্গনের অকুতোভয় সেনাপতি (#৮৩)",
    "birthAndDeathBn": "জন্ম: কাবার অভ্যন্তরে (হিজরতের ৬০ বছর পূর্বে) | ওফাত: ৫৪ হিজরি মদিনা (১২০ বছর)",
    "summaryBn": "ইতিহাসের একমাত্র ব্যক্তি যাঁর জন্ম হয়েছিল স্বয়ং পবিত্র কাবার অভ্যন্তরে; উম্মুল মুমিনীন খাদিজা (রা.)-এর আপন ভাতিজা; যিনি রাসুলের কাছে জীবনে একবার চেয়ে পরে অঙ্গীকার করেছিলেন দুনিয়ায় আর কখনো কারও কাছে হাত পাতবেন না এবং ১২০ বছর বেঁচে তা রক্ষা করেছিলেন।",
    "detailedBiographyBn": "হযরত হাকিম ইবনে হিযাম (রা.) ছিলেন আরবের এক অনন্য মর্যাদাবান ব্যক্তিত্ব। তাঁর গর্ভবতী মা কাবার ভেতরে প্রবেশ করার পর প্রসববেদনা উঠলে কাবার চামড়ার চাটাইয়ের ওপর হাকিমের জন্ম হয়। কাবার ভেতরে জন্ম নেওয়া মানুষের ইতিহাসে তিনিই একমাত্র ব্যক্তি। তিনি ছিলেন উম্মুল মুমিনীন খাদিজা (রা.)-এর আপন ভাতিজা এবং জাহেলি যুগে কুরাইশদের শীর্ষ বিচারক ও দারুন নদওয়ার প্রধান ছিলেন।\n\nশিয়াবে আবি তালিবে যখন রাসুল ও মুসলমানরা তিন বছর বয়কটের শিকার হয়ে অনাহারে ছিলেন, তখন হাকিম রাতের আঁধারে নিজের উটের পিঠে আটা ও খেজুর বোঝাই করে গোপনে গিরিখাতে পাঠিয়ে রাসুল ও মুসলমানদের জীবন বাঁচাতেন। ৮ হিজরিতে মক্কা বিজয়ের দিন তিনি ইসলাম গ্রহণ করেন।\n\nহুনাইন যুদ্ধের পর তিনি রাসুল (সা.)-এর কাছে গনিমত চাইলেন। রাসুল তাঁকে একশটি উট দিলেন। তিনি আবার চাইলেন, রাসুল আরও একশটি উট দিলেন। এরপর রাসুল (সা.) স্নেহভরে একটি ঐতিহাসিক উপদেশ দিয়ে বললেন: \"হে হাকিম! নিশ্চয়ই এই ধনসম্পদ অত্যন্ত মিষ্টি ও আকর্ষণীয়! যে ব্যক্তি অন্তরের নির্লোভ অবস্থায় তা গ্রহণ করে, তার জন্য তাতে বরকত দেওয়া হয়। আর যে ব্যক্তি লোভের সাথে তা চায়, তার জন্য তাতে কোনো বরকত দেওয়া হয় না; সে ওই ব্যক্তির মতো যে খায় কিন্তু পেট ভরে না! আর জেনে রেখো, উপরের হাত (দাতার হাত) নিচের হাতের (গ্রহীতার হাত) চেয়ে শ্রেষ্ঠ!\" হাকিম এই বাণীতে চমকে উঠে বললেন: \"হে আল্লাহর রাসুল! সেই সত্তার শপথ যিনি আপনাকে সত্যসহ পাঠিয়েছেন, আপনার পর মৃত্যুর আগ পর্যন্ত আমি পৃথিবীর আর কোনো মানুষের কাছে একটি পয়সাও চাইব না!\" আবু বকর ও উমর (রা.) খলিফা থাকাকালে তাঁকে বায়তুল মাল থেকে তাঁর প্রাপ্য ভাতা দিতে চাইলেও তিনি তা গ্রহণ করেননি।",
    "islamAcceptanceBn": "৮ হিজরিতে মক্কা বিজয়ের সময় ইসলাম গ্রহণ করেন।",
