    "birthAndDeathBn": "জন্ম: আবিসিনিয়া | ওফাত: খলিফা উসমানের আমলে হিমস, সিরিয়া",
    "summaryBn": "আবিসিনীয় দাস যিনি উহুদের যুদ্ধে বর্শা ছুড়ে রাসুলের প্রিয় চাচা বীর হামজা (রা.)-কে শহীদ করেছিলেন; কিন্তু পরবর্তীতে খাঁটি তওবা করে ইসলাম গ্রহণ করেন এবং একই বর্শা দিয়ে ভণ্ড নবি মুসায়লামা কাজ্জাবকে হত্যা করে প্রায়শ্চিত্ত করেছিলেন।",
    "detailedBiographyBn": "হযরত ওয়াহশি ইবনে হারব (রা.) ছিলেন জুবায়ের ইবনে মুতঈমের আবিসিনীয় ক্রীতদাস। তিনি দূর থেকে বর্শা নিক্ষেপে ছিলেন আরবের অদ্বিতীয় লক্ষ্যভেদী। উহুদ যুদ্ধে তাঁর মালিক তাঁকে প্রতিশ্রুতি দিয়েছিল যে হামজা (রা.)-কে হত্যা করতে পারলে তাঁকে দাসত্ব থেকে চিরতরে মুক্তি দেওয়া হবে। উহুদের ময়দানে পাথরের আড়ালে ওত পেতে থেকে তিনি তাঁর বিষাক্ত বর্শা নিক্ষেপ করে বীর হামজাকে শহীদ করেন।\n\n৮ হিজরিতে মক্কা বিজয়ের পর ওয়াহশি তায়েফে পালিয়ে যান। কিন্তু ৯ হিজরিতে যখন তায়েফের লোকেরা ইসলাম গ্রহণ করতে মদিনায় যায়, তখন ওয়াহশি এক চরম মানসিক দ্বন্দ্বে পড়েন। মানুষ তাঁকে বলল: \"মুহাম্মদ এমন এক নবি যিনি তওবাকারীকে কখনো ফিরিয়ে দেন না!\" ওয়াহশি মদিনায় এসে রাসুলুল্লাহ (সা.)-এর সামনে দাঁড়িয়ে কালিমায়ে শাহাদাত পাঠ করলেন। রাসুল (সা.) মাথা তুলে বললেন: \"তুমি কি ওয়াহশি?\" তিনি বললেন: \"জী, হে আল্লাহর রাসুল!\" রাসুল (সা.) বললেন: \"তুমি কি আমাকে শোনাবে কীভাবে তুমি আমার চাচা হামজাকে হত্যা করেছিলে?\" ওয়াহশি পুরো ঘটনা শোনালেন। রাসুলুল্লাহ (সা.)-এর চোখ দিয়ে অশ্রুধারা বইতে লাগল। রাসুল (সা.) বললেন: \"ওয়াহশি! তুমি কি পারো তোমার চেহারাটি আমার সামনে থেকে আড়ালে রাখতে? কারণ তোমাকে দেখলে আমার চাচার রক্তমাখা স্মৃতি মনে পড়ে যায়।\" ওয়াহশি বললেন: \"আমি মেনে নিলাম।\" এরপর থেকে ওয়াহশি কোনোদিন রাসুলের সরাসরি মুখোমুখি হননি, আড়ালে দাঁড়িয়ে নামাজ পড়তেন।\n\nওয়াহশি বলতেন: \"আমি জাহেলিয়্যাতে মানুষের মধ্যে সর্বশ্রেষ্ঠ মানুষটিকে হত্যা করেছিলাম, তাই আমি শপথ করেছিলাম যে ইসলামে এসে মানুষের মধ্যে সবচেয়ে নিকৃষ্ট কাফেরটিকে হত্যা করে তার প্রায়শ্চিত্ত করব!\" ১২ হিজরিতে ইয়ামামার যুদ্ধে ওয়াহশি সেই একই ঐতিহাসিক বর্শাটি হাতে নিয়ে ময়দানে নামেন এবং ভণ্ড নবি মুসায়লামা কাজ্জাবের বুকে তা নিক্ষেপ করে তাকে হত্যা করেন। তিনি গর্ব করে বলতেন: \"আমি জাহেলিয়্যাতে শ্রেষ্ঠ মানুষকে হত্যা করেছি, আর ইসলামে নিকৃষ্টতম ভণ্ডকে হত্যা করেছি!\"",
    "islamAcceptanceBn": "৯ হিজরিতে তায়েফের প্রতিনিধিদলের সাথে এসে রাসুল (সা.)-এর পবিত্র দরবারে ক্ষমা চেয়ে ইসলাম গ্রহণ করেন।",
