        "title": "মুসায়লামার বুকে বর্শা ও ওয়াহশির আত্মতৃপ্তি",
        "story": "ইয়ামামার যুদ্ধে 'মৃত্যুর বাগান' দুর্গে যখন মুসায়লামা উন্মাদ হয়ে তলোয়ার চালাচ্ছিল, ওয়াহশি বলেন: আমি আমার সেই পুরনো বর্শাটি তুলে নিলাম যার মাধ্যমে আমি উহুদে হামজাকে শহীদ করেছিলাম। আমি লক্ষ্য স্থির করলাম। এরপর বর্শাটি সজোরে ছুড়তেই তা সরাসরি মুসায়লামার বুকের মাঝখানে বিঁধে এপাশ-ওপাশ হয়ে গেল। সাথে সাথে আবু দুজানা গিয়ে তার ওপর তলোয়ারের আঘাত হানল। মুসায়লামা মাটিতে লুটিয়ে পড়তেই আমি চিৎকার করে বলে উঠলাম: \"হে আমার রব! আমি আমার জাহেলিয়্যাতের সেই জঘন্য পাপের কাফফারা হিসেবে আজ ইসলামের চরম শত্রু এই ভণ্ডকে নিকেশ করলাম!\""
