    "nameAr": "نعيم بن مسعود الأشجعي رضي الله عنه",
    "titleBn": "খন্দক যুদ্ধের মনস্তাত্ত্বিক বিজয়ের একক রূপকার",
    "categoryKey": "commanders",
    "categoryBn": "রণাঙ্গনের অকুতোভয় সেনাপতি (#৮৬)",
    "birthAndDeathBn": "জন্ম: নজদ | ওফাত: ৩৫ হিজরি মদিনা",
    "summaryBn": "খন্দকের চরম সংকটে রাতের অন্ধকারে একাকী এসে ইসলাম গ্রহণ করা গাতফান নেতা; যাঁর একক অবিশ্বাস্য বুদ্ধিমত্তা ও মনস্তাত্ত্বিক কৌশলে কুরাইশ, গাতফান ও ইহুদি বনু কুরাইজার ঐক্য ভেঙে চুরমার হয়ে যায় এবং রক্তপাতহীন বিজয় অর্জিত হয়।",
    "detailedBiographyBn": "হযরত নুআইম ইবনে মাসউদ আল-আশজাঈ (রা.) ছিলেন নজদের প্রভাবশালী গাতফান গোত্রের অত্যন্ত বুদ্ধিমান ও বাকপটু সর্দার। ৫ হিজরিতে খন্দকের (আহযাবের) যুদ্ধে যখন দশ হাজার কাফেরের সম্মিলিত বাহিনী মদিনাকে চারদিক থেকে ঘিরে ফেলেছিল এবং মদিনার ভেতরে বনু কুরাইজা ইহুদিরা বিশ্বাসঘাতকতা করেছিল, তখন মুসলিমরা চূড়ান্ত ধ্বংসের মুখে পড়েন।\n\nঠিক সেই সংকটের এক রাতে নুআইম গোপনে পরিখা পেরিয়ে রাসুলুল্লাহ (সা.)-এর তাঁবুতে প্রবেশ করেন। তিনি বললেন: \"হে আল্লাহর রাসুল! আমি ইসলাম গ্রহণ করেছি, কিন্তু আমার নিজের গোত্র বা কুরাইশদের কেউই এখনো আমার ইসলাম গ্রহণের কথা জানে না! আপনি আমাকে যা আদেশ করবেন আমি তা-ই করতে প্রস্তুত!\" রাসুলুল্লাহ (সা.) এক ঐতিহাসিক কৌশলগত বাণী দিলেন: \"আল-হারবু খুদ’আহ!\" (যুদ্ধ তো এক কৌশল ও চালবাজি!)। তুমি একা মানুষ, তবে তুমি তাদের ঐক্যে ফাটল ধরাতে পারলে চেষ্টা করো!\n\nনুআইম একাই সেই রাতে কাফেরদের মহাজোটে চরম ফাটল ধরিয়ে দেন। প্রথমে তিনি ইহুদি বনু কুরাইজার কাছে গিয়ে বললেন: \"কুরাইশ ও গাতফান বহিরাগত, তারা টিকতে না পারলে মক্কায় পালাবে; তখন মুহাম্মদ কিন্তু তোমাদেরই ঘিরে ফেলবে! তাই মুহাম্মদকে আক্রমণের আগে কুরাইশদের কয়েকজন শীর্ষ নেতাকে তোমাদের কাছে জিম্মি হিসেবে বন্ধক রাখতে বলো!\" ইহুদিরা তাঁর কথায় বিশ্বাস করল। এরপর তিনি সোজা আবু সুফিয়ানের কুরাইশ শিবিরে গিয়ে বললেন: \"বনু কুরাইজা কিন্তু মুহাম্মদের সাথে গোপন চুক্তি করেছে! তারা তোমাদের কাছে জিম্মি চাইবে এবং তাদের মুহাম্মদের হাতে তুলে দিয়ে হত্যা করাবে!\" এরপর তিনি গাতফান শিবিরে গিয়েও একই কথা বললেন। পরদিন যখন আবু সুফিয়ান ইহুদিদের বলল কালই একযোগে আক্রমণ হবে, ইহুদিরা বলল: \"আগে কুরাইশদের সর্দারদের আমাদের কাছে বন্ধক রাখো!\" আবু সুফিয়ান চিৎকার করে বলল: \"নুআইম সত্যি বলেছিল! ইহুদিরা গাদ্দার!\" এভাবে কোনো তলোয়ার ছাড়াই নুআইমের বুদ্ধিমত্তায় কাফেরদের সুবিশাল জোট ছিন্নভিন্ন হয়ে যায়।",
    "islamAcceptanceBn": "খন্দক যুদ্ধের চরম উত্তেজনার মাঝে এক রাতে গোপনে রাসুল (সা.)-এর দরবারে এসে ইসলাম গ্রহণ করেন।",
