        "title": "খন্দকের রাতে রাসুলের তাঁবুতে প্রবেশ",
        "story": "নুআইম যখন রাতের আঁধারে মাটি মেখে রাসুলের তাঁবুতে ঢুকলেন, রাসুল (সা.) বিস্মিত হয়ে বললেন: \"নুআইম ইবনে মাসউদ?\" নুআইম বললেন: \"জী হে আল্লাহর রাসুল! আমি সাক্ষ্য দিচ্ছি আল্লাহ ছাড়া মাবুদ নেই এবং আপনি আল্লাহর রাসুল! আমি মুসলমান হয়ে গেছি কিন্তু কাফেররা তা জানে না। আমাকে আপনি যা নির্দেশ করবেন আমি তা-ই করব।\" রাসুল (সা.) তাঁর মাথায় হাত রেখে মুচকি হেসে বললেন: \"নুআইম! তুমি তো আমাদের মাঝে একা এক মানুষ, যদি পারো ওদের মাঝে ফাটল ধরাও; যুদ্ধ তো কৌশলেরই নাম!\" নুআইম একা কাফের শিবিরে গিয়ে এমন অভিনয় করলেন যা গোটা যুদ্ধের ইতিহাস বদলে দিয়েছিল।"
