    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: ৭২ হিজরি কুফা (৮০+ বছর)",
    "summaryBn": "মদিনার প্রাজ্ঞ আনসার সাহাবি, যিনি শৈশবে হিজরতের সময় রাসুলের আগমন স্বচক্ষে দেখেছিলেন; যিনি ১৫টি বড় যুদ্ধে অংশ নেন এবং কবরের জীবনের সওয়াল-জওয়াব ও আযাবের সবচেয়ে বিস্তারিত হাদিসের প্রধান বর্ণনাকারী।",
    "detailedBiographyBn": "হযরত বারাআ ইবনে আযিব (রা.) ছিলেন মদিনার আওস গোত্রের বনু হারিসা শাখার সন্তান। রাসুলুল্লাহ (সা.) যখন মদিনায় হিজরত করেন, বারাআ তখন ছোট বালক ছিলেন। তিনি মদিনার অলিগলিতে ছোট বাচ্চাদের সাথে আনন্দে সুর মিলিয়ে বলতেন: \"তালাআল বাদরু আলাইনা, মিন সানিয়্যাতিল ওয়াদা’!\"\n\nবদর যুদ্ধে তিনি এবং আব্দুল্লাহ ইবনে উমর অপ্রাপ্তবয়স্ক হওয়ায় রাসুল (সা.) তাঁদের ফিরিয়ে দেন। উহুদ ও খন্দক থেকে শুরু করে তিনি রাসুলুল্লাহ (সা.)-এর সাথে মোট ১৫টি যুদ্ধে অংশগ্রহণ করেন। হুদায়বিয়ার সন্ধিতে তিনি উপস্থিত ছিলেন এবং বাবলা গাছের নিচে বাইয়াতে রিদওয়ানে অংশ নেন।\n\nবারাআ ইবনে আযিব ছিলেন একজন প্রখ্যাত মুহাদ্দিস (৩০৫টি হাদিস বর্ণিত)। তিনি রাসুল (সা.)-এর চেহারা মোবারকের রূপ ও সৌন্দর্যের চমৎকার বর্ণনা দিতেন: \"রাসুলুল্লাহ (সা.) ছিলেন মানুষের মধ্যে সর্বাধিক সুন্দর এবং চরিত্রের দিক থেকে শ্রেষ্ঠতম!\" মানুষের মৃত্যুর পর কবরের মাটি চাপা দেওয়ার দৃশ্য এবং মুনকার-নাকিরের সওয়াল-জওয়াবের যে বিশদ ও রোমহর্ষক হাদিস মুসলিম বিশ্বে সুপরিচিত, তা হযরত বারাআ ইবনে আযিবই বিশ্বস্ত সনদে বর্ণনা করেছেন। খলিফা আলীর খেলাফতকালে তিনি কুফায় বসবাস করেন এবং জঙ্গে জামাল, সিফফিন ও নাহরাওয়ানে আলীর পক্ষে অংশ নেন।",
    "islamAcceptanceBn": "মদিনায় হিজরতের পূর্বেই পিতার সাথে ইসলাম গ্রহণ করেন এবং কুরআনের সূরাগুলো মুখস্থ করতে থাকেন।",
