        "title": "রাসুল (সা.)-এর সৌন্দর্যের সেই জীবন্ত বর্ণনা",
        "story": "কুফায় একবার এক ব্যক্তি বারাআ ইবনে আযিবকে জিজ্ঞাসা করল: \"রাসুলুল্লাহ (সা.)-এর চেহারা মোবারক কি তরবারির মতো চকচকে ছিল?\" বারাআ (রা.) আবেগে আপ্লুত হয়ে বললেন: \"না! তরবারির মতো নয়, বরং তাঁর পবিত্র মুখমণ্ডল ছিল পূর্ণিমার উজ্জ্বল চাঁদের মতো গোল ও স্নিগ্ধ জ্যোতির্ময়!\" বারাআ আরও বলতেন: \"আমি একবার লাল রঙের জুব্বা পরিহিত অবস্থায় রাসুলকে দেখেছিলাম, আল্লাহর কসম! রাসুলের চেয়ে সুন্দর দৃশ্য আমি আমার জীবনে আর কখনোই দেখিনি!\""
