    "detailedBiographyBn": "হযরত জারির ইবনে আব্দুল্লাহ আল-বাজালি (রা.) ছিলেন ইয়েমেনের পরাক্রমশালী বাজিলাহ গোত্রের প্রধান। তিনি রাসুলুল্লাহ (সা.)-এর জীবনের শেষ বছর অর্থাৎ ১০ হিজরির রমজান মাসে নিজের গোত্রের বিশাল কাফেলা নিয়ে মদিনায় এসে ইসলাম গ্রহণ করেন।\n\nতিনি ছিলেন আরবের এক অনন্য রূপবান, দীর্ঘদেহী ও প্রভাবশালী পুরুষ। খলিফা উমর ইবনুল খাত্তাব (রা.) তাঁর রূপ-লাবণ্য দেখে বলেছিলেন: \"জারির ইবনে আব্দুল্লাহ হলো এই উম্মতের ইউসুফ (আ.)!\"\n\nজারির (রা.) বলেন: \"আমি যখন থেকে ইসলাম গ্রহণ করেছি, রাসুলুল্লাহ (সা.) কোনোদিন তাঁর ঘরে প্রবেশ করতে আমাকে বাধা দেননি এবং যখনই তিনি আমার চেহারার দিকে তাকাতেন, তখনই তিনি পরম মমতায় আমার দিকে তাকিয়ে এক অনাবিল মধুর হাসিতে মুখ ভরিয়ে দিতেন!\" রাসুল (সা.) তাঁকে ইয়েমেনের বিখ্যাত কায়েস গোত্রের মূর্তিমন্দির ‘জুল খালাসাহ’ (যাকে কাফেররা ইয়ামানি কাবা বলত) ধ্বংস করার নির্দেশ দেন। জারির বললেন: \"হে আল্লাহর রাসুল! আমি তো ঘোড়ার পিঠে ঠিকমতো বসতে পারি না, পড়ে যাই!\" রাসুলুল্লাহ (সা.) নিজের বরকতময় হাত জারিরের বুকের মাঝখানে এমন জোরে মারলেন যে জারির বলেন: \"আমি আমার বুকের ভেতরে রাসুলের মোবারক আঙুলের শীতল পরশ অনুভব করলাম!\" এরপর রাসুল দোয়া করলেন: \"হে আল্লাহ! একে ঘোড়ার পিঠে অবিচল রাখুন এবং একে হেদায়াতপ্রাপ্ত ও পথপ্রদর্শক বানান!\" এরপর জারির আর কোনোদিন ঘোড়া থেকে পড়েননি এবং জুল খালাসার মূর্তিমন্দির জ্বালিয়ে ভস্ম করে দেন। কাদিসিয়ার যুদ্ধে তিনি বাজিলাহ গোত্রের নেতৃত্ব দেন।",
    "islamAcceptanceBn": "১০ হিজরিতে রাসুলুল্লাহ (সা.)-এর ওফাতের মাত্র কয়েকমাস পূর্বে ইয়েমেন থেকে এসে ইসলাম গ্রহণ করেন।",
