        "story": "মুতাররিফ ইবনে আব্দুল্লাহ বলেন: একবার আমি ইমরান ইবনে হুসাইনের সাথে দেখা করতে গেলাম। তিনি তখন মারাত্মক যন্ত্রণায় ছটফট করছেন কিন্তু মুখে আলহামদুলিল্লাহ বলছেন। আমার চোখ দিয়ে পানি পড়তে দেখে ইমরান বললেন: \"মুতাররিফ! কাঁদছ কেন?\" আমি বললাম: \"আপনার এই নিদারুণ কষ্ট আমি সহ্য করতে পারছি না!\" ইমরান মুচকি হেসে বললেন: \"কেঁদো না ভাই! আল্লাহ আমার জন্য যা ভালো মনে করেছেন, আমিও তা ভালো মনে করি। আর তোমাকে একটি গোপন কথা বলি যা আমার মৃত্যুর আগে কাউকে বলবে না—নিশ্চয়ই আসমানের ফেরেশতারা প্রতিদিন আমার কাছে আগমন করে এবং আমাকে স্পষ্ট আওয়াজে সালাম জানায়! আমি নিজের কানে তাদের সালামের ধ্বনি শুনতে পাই! যে অসুস্থতা আমাকে ফেরেশতাদের সালামের স্বাদ এনে দেয়, তা কখনো আমার জন্য কষ্টকর হতে পারে না!\""
