    "detailedBiographyBn": "হযরত উতবা ইবনে গজওয়ান (রা.) ছিলেন ইসলামের সূচনাপর্বের সপ্তমতম মুসলমান। তিনি অত্যন্ত দক্ষ তীরন্দাজ ছিলেন। কাফেরদের অমানবিক নির্যাতন সহ্য করে তিনি হাবশায় এবং পরবর্তীতে মদিনায় হিজরত করেন। তিনি বদর, উহুদ ও খন্দকসহ রাসুলুল্লাহ (সা.)-এর সমস্ত যুদ্ধে বীরত্ব দেখান।\n\n১৪ হিজরিতে খলিফা উমর ফারুক (রা.) তাঁকে একটি সেনাদল দিয়ে ইরাকের দক্ষিণাঞ্চলে পারস্য উপসাগরের প্রবেশদ্বারে সামরিক ছাউনি গড়ার জন্য পাঠান যাতে পারসিকরা সমুদ্রপথে কোনো সাহায্য না পায়। উতবা সেখানে পৌঁছে পারসিকদের পরাস্ত করেন এবং সেখানে এক নতুন আধুনিক নগরীর ভিত্তি স্থাপন করেন, যা ইতিহাসে ‘বসরা নগরী’ নামে বিখ্যাত। তিনিই বসরার সর্বপ্রথম জামে মসজিদ নির্মাণ করেন যা বাঁশ ও নলখাগড়া দিয়ে তৈরি হয়েছিল।\n\nবসরার বিপুল ধনসম্পদ ও বিজয় তাঁর পায়ে লুটিয়ে পড়লেও উতবা ছিলেন চরম অনাড়ম্বর ও দুনিয়াবিমুখ। তিনি একদিন বসরার মিম্বারে দাঁড়িয়ে সাহাবিদের স্মরণ করিয়ে দেন: \"আমি রাসুল (সা.)-এর সাথে এমন দিনে ছিলাম যখন আমরা সাতজন ছাড়া আর কোনো মুসলমান ছিল না; আমাদের খাবারের কিছু ছিল না বলে গাছের পাতা খেয়ে আমাদের ঠোঁটে ঘা হয়ে গিয়েছিল! আর আজ দেখো, আমাদের প্রত্যেকে কোনো না কোনো প্রদেশের গভর্নর! আমি আল্লাহর কাছে আশ্রয় চাই এমন ব্যক্তি হওয়া থেকে যে মানুষের কাছে বড় কিন্তু আল্লাহর কাছে ছোট!\" ১৭ হিজরিতে তিনি হজ শেষে খলিফা উমরকে গভর্নরশিপ থেকে অব্যাহতির অনুরোধ জানাতে মদিনায় আসেন এবং ফেরার পথে ইন্তেকাল করেন।",
