        "story": "খালিদ ইবনে উমাইর বর্ণনা করেন: উতবা ইবনে গজওয়ান বসরার মিম্বারে দাঁড়িয়ে খুতবা দিলেন। আল্লাহর প্রশংসা করার পর তিনি ফুঁপিয়ে কেঁদে উঠলেন। তিনি বললেন: \"হে লোকসকল! দুনিয়া তার পিঠ ফিরিয়ে চলে যাচ্ছে। তোমরা এর সামান্য প্রসাদ পেয়ে বিভ্রান্ত হয়ো না! আমি সেই দিন দেখেছি যখন আমি রাসুলের সাথে সপ্তম ব্যক্তি হিসেবে ছিলাম। গাছের শুকনা পাতা চিবিয়ে চিবিয়ে আমাদের মুখের চোয়াল ক্ষতবিক্ষত হয়ে গিয়েছিল। একবার আমি একটি চাদর পেয়ে তা ছিঁড়ে দুই টুকরো করেছিলাম—এক টুকরো আমি পরেছিলাম আর এক টুকরো সা’দ ইবনে আবি ওয়াক্কাস পরেছিল! আর আজ আমরা বড় বড় শহরের গভর্নর! আল্লাহর কসম, আমি এমন বড় হওয়াকে ধিক্কার জানাই যা আল্লাহর দরবারে মানুষকে তুচ্ছ করে দেয়!\" তাঁর এই কান্না দেখে পুরো মসজিদের মানুষ ডুকরে কেঁদে উঠেছিল।"
