    "summaryBn": "প্রাচীন আরবের শীর্ষ চার কূটনীতিবিদের অন্যতম; হুদায়বিয়ার সন্ধিতে তলোয়ার হাতে রাসুল (সা.)-এর পাশে পাহাড়ের মতো দাঁড়িয়ে নিজের চাচার হাত তরবারির বাট দিয়ে আঘাত করে সরিয়ে দেওয়া নির্ভীক সাহাবি; কাদিসিয়ার যুদ্ধে পারস্য সেনাপতির দরবারে নির্ভীক রাষ্ট্রদূত।",
    "detailedBiographyBn": "হযরত আল-মুগিরা ইবনে শুবা আস-সাকাফী (রা.) ছিলেন তায়েফের বনু সাকীফ গোত্রের অত্যন্ত চতুর, দীর্ঘদেহী ও প্রভাবশালী নেতা। ৫ হিজরিতে খন্দক যুদ্ধের সময় তিনি মদিনায় এসে ইসলাম গ্রহণ করেন।\n\n৬ হিজরিতে হুদায়বিয়ার ঐতিহাসিক সন্ধির সময় কুরাইশদের প্রতিনিধি হয়ে এসেছিলেন তাঁরই আপন চাচা উরওয়া ইবনে মাসউদ। উরওয়া আরবের প্রথা অনুযায়ী রাসুল (সা.)-এর সাথে কথা বলার সময় রাসুলের দাড়ি মোবারক স্পর্শ করার চেষ্টা করছিল। পাশে লোহার বর্ম ও শিরস্ত্রাণ পরে উন্মুক্ত তলোয়ার হাতে অতন্দ্র প্রহরীর মতো দাঁড়িয়েছিলেন মুগিরা। তিনি তলোয়ারের বাট দিয়ে চাচার হাতে সজোরে আঘাত করে গর্জে উঠলেন: \"মুহাম্মদ (সা.)-এর পবিত্র দাড়ি থেকে নিজের হাত দূরে রাখো, নয়তো এই হাত আর ফিরে যাবে না!\" উরওয়া ক্ষিপ্ত হয়ে বলল: \"কে এই ব্যক্তি?\" রাসুল মুচকি হেসে বললেন: \"ইনি তোমার ভাতিজা মুগিরা!\" উরওয়া মক্কায় ফিরে কাফেরদের বলেছিল: \"আমি রোম ও পারস্যের রাজদরবারে গিয়েছি, কিন্তু মুহাম্মদকে তাঁর সঙ্গীরা যেভাবে সম্মান করে, পৃথিবীর কোনো রাজা তার প্রজাদের কাছ থেকে এমন সম্মান পায় না!\"\n\nমুগিরা ছিলেন আরবের ‘দাহিয়াতুল আরব’ (আরবের প্রখর কূটনৈতিক বুদ্ধিজীবী)। কাদিসিয়ার যুদ্ধের প্রাক্কালে পারস্যের অহংকারী সর্বাধিনায়ক রুস্তমের দরবারে মুসলিম রাষ্ট্রদূত হিসেবে গিয়ে তিনি পারস্যের স্বর্ণখচিত গালিচায় তলোয়ার দিয়ে ফুটো করে রুস্তমের সিংহাসনে উঠে বসে নির্ভীক বক্তব্য দিয়েছিলেন। তিনি খলিফা উমর ও মুয়াবিয়ার আমলে বসরা ও কুফার সফল গভর্নর ছিলেন।",
    "islamAcceptanceBn": "৫ হিজরিতে খন্দকের যুদ্ধের সময় মদিনায় এসে রাসুল (সা.)-এর হাতে ইসলাম গ্রহণ করেন।",
