    "emotionalStoriesBn": [
      {
        "title": "রুস্তমের স্বর্ণের দরবারে মুগিরার প্রবেশ",
        "story": "কাদিসিয়ার যুদ্ধের পূর্বে পারস্য সেনাপতি রুস্তম মুসলিমদের ভয় দেখাতে তার দরবার স্বর্ণ, মণি-মুক্তা ও রেশমি গালিচায় সাজাল। মুগিরা সাধারণ পোশাকে নিজের ঘোড়ায় চড়ে সোজা সেই রেশমি গালিচার ওপর উঠে গেলেন। ঘোড়া থেকে নেমে তিনি নিজের ধারালো তরবারি দিয়ে মূল্যবান বালিশ ও গালিচা চিরে দিয়ে সোজা রুস্তমের সিংহাসনে গিয়ে তার পাশে বসে পড়লেন! পারসিক প্রহরীরা তাঁকে টেনে নামাতে চাইলে মুগিরা বজ্রকণ্ঠে বললেন: \"আমরা ভাবতাম তোমরা সুবিচারক জাতি! কিন্তু আজ দেখলাম তোমরা নিকৃষ্ট দাস! আমাদের আরবে সাধারণ মানুষও নেতার পাশে বসে, আর তোমরা এক মানুষকে খোদা বানিয়ে রেখেছ!\" তাঁর এই নির্ভীক পৌরুষ দেখে রুস্তমের পুরো দরবার ভয়ে কেঁপে উঠেছিল।"
      }
    ],
