    "summaryBn": "মক্কার প্রাথমিক যুগের সম্মানিত মুহাজির ও রাসুলুল্লাহ (সা.)-এর ওহী লেখক সাহাবি; খলিফা আবু বকর (রা.) সিরিয়া অভিযানের জন্য যে চারজন প্রধান সেনাপতিকে মনোনয়ন দিয়েছিলেন, শুরাহবিল ছিলেন তাঁদের অন্যতম যিনি সমগ্র জর্ডান অঞ্চল বিজয় করেছিলেন।",
    "detailedBiographyBn": "হযরত শুরাহবিল ইবনে হাসানা (রা.) ছিলেন ইসলামের একেবারে প্রাথমিক যুগের অন্যতম অগ্রণী সাহাবি। তিনি তাঁর মাতা হাসানার পরিচয়ে বেশি খ্যাত ছিলেন। মক্কার কুরাইশদের অত্যাচারের মুখে তিনি হাবশায় দ্বিতীয় কাফেলায় হিজরত করেন এবং পরবর্তীতে মদিনায় এসে রাসুলের সাথে মিলিত হন।\n\nতিনি ছিলেন একজন সুশিক্ষিত ও সুন্দর হস্তাক্ষরের অধিকারী সাহাবি। রাসুলুল্লাহ (সা.) মদিনায় তাঁকে ওহী লিপিবদ্ধ করার মহান দায়িত্ব অর্পণ করেন। তিনি রাসুলের উপস্থিতিতে বহু চিঠি ও সন্ধিপত্রও লিখেছিলেন।\n\nরাসুলুল্লাহ (সা.)-এর ওফাতের পর খলিফা আবু বকর (রা.) যখন রোমান সাম্রাজ্যের বিরুদ্ধে শাম (সিরিয়া) বিজয়ের জন্য চারটি পৃথক সেনাদল গঠন করেন, তখন তিনি শুরাহবিল ইবনে হাসানাকে একটি সুবিশাল বাহিনীর প্রধান সেনাপতি করে জর্ডানের দিকে পাঠান। তিনি বুসরা ও আজনাদাইনের যুদ্ধে অসীম সাহসিকতা দেখান এবং সমগ্র জর্ডান অঞ্চলকে ইসলামি খিলাফতের অন্তর্ভুক্ত করেন। পরবর্তীতে আবু উবাইদা (রা.)-এর অধীনে তিনি ইয়ারমুকের মহাযুদ্ধে পদাতিক বাহিনীর এক অংশের নেতৃত্ব দিয়ে রোমানদের শোচনীয় পরাজয় নিশ্চিত করেন। ১৮ হিজরিতে শামের ঐতিহাসিক ‘আমওয়াস’ প্লেগ মহামারীতে আক্রান্ত হয়ে আবু উবাইদা ও মুআযের সাথেই তিনি শাহাদাত বরণ করেন।",
    "islamAcceptanceBn": "মক্কার সূচনাতেই দারুল আরকামে যাওয়ার আগেই ইসলাম গ্রহণ করেন এবং হাবশায় হিজরত করেন।",
