        "title": "খলিফা আবু বকরের পায়ে হেঁটে বিদায় জানানো",
        "story": "শাম অভিযানের উদ্দেশ্যে যখন সেনাপতি শুরাহবিল নিজের ঘোড়ায় চড়ে মদিনা থেকে বের হচ্ছিলেন, খলিফা আবু বকর সিদ্দিক (রা.) খালি পায়ে হেঁটে তাঁর ঘোড়ার সাথে সাথে বহুদূর পর্যন্ত পথ চলছিলেন। শুরাহবিল অত্যন্ত লজ্জিত হয়ে বললেন: \"হে খলিফাতু রাসুলিল্লাহ! আপনি ঘোড়ায় চড়ুন নয়তো আমাকে নামতে দিন, আমি কিছুতেই রাসুলের খলিফাকে হেঁটে চলতে দেখে নিজে ঘোড়ায় চড়ে যেতে পারি না!\" আবু বকর (রা.) পরম স্নেহে বললেন: \"হে শুরাহবিল! তুমিও নামবে না আর আমিও চড়ব না! আমি আল্লাহর রাস্তায় আমার এই পা দুটিকে ধূলিমলিন করতে চাই, কারণ আল্লাহর রাস্তায় যার পা ধূলিমলিন হয়, আল্লাহ তার পুরো শরীরকে জাহান্নামের জন্য হারাম করে দেন!\""
