        "textBn": "আয়েশা (রা.) বলতেন: \"সমস্ত প্রশংসা সেই আল্লাহর যাঁর শ্রবণশক্তি সমস্ত কিছুকে পরিবেষ্টন করে আছে! খাওলা ঘরের এক কোণে দাঁড়িয়ে রাসুলের কাছে ফরিয়াদ করছিল, আমি একই ঘরে থেকেও কিছু কথা শুনতে পাচ্ছিলাম না; অথচ স্বয়ং আল্লাহ সাত আসমানের ওপর থেকে তাঁর পুরো কথা শুনে আয়াত নাজিল করলেন!\"",
        "source": "সহিহ বুখারি: ৭৩৮৫, সুনানে নাসায়ী"
