    "deathOrMartyrdomBn": "৬২ হিজরিতে কারবালার ঘটনার কিছুদিন পর মদিনায় ৮৪ বছর বয়সে উম্মুল মুমিনীনদের মধ্যে সর্বশেষ হিসেবে ইন্তেকাল করেন। জান্নাতুল বাকিতে তাঁকে সমাহিত করা হয়।",
