    "birthAndDeathBn": "জন্ম: মদিনা | ওফাত: খলিফা উসমানের আমলে মদিনা",
    "summaryBn": "হযরত আনাস ইবনে মালিক (রা.)-এর মহীয়সী গর্ভধারিণী মাতা; যাঁর দেনমোহর ছিল আবু তালহার ইসলাম গ্রহণ; যাঁর পদশব্দ স্বয়ং বিশ্বনবী মিরাজের রাতে জান্নাতে শুনতে পেয়েছিলেন; যিনি নিজের সন্তানের মৃত্যুতে অতুলনীয় সবরের পরাকাষ্ঠা দেখিয়েছিলেন।",
    "detailedBiographyBn": "হযরত উম্মে সুলাইম বিনতে মিলহান আল-আনসারিয়্যাহ (রা.) ছিলেন ইসলামের ইতিহাসের অন্যতম শ্রেষ্ঠ বুদ্ধিমতী ও ঈমানদার নারী। মদিনায় রাসুলুল্লাহ (সা.)-এর দাওয়াত পৌঁছামাত্র তিনি ইসলাম গ্রহণ করেন। তাঁর প্রথম স্বামী মালিক ইবনে নাদর ইসলাম গ্রহণে অস্বীকৃতি জানিয়ে ক্ষিপ্ত হয়ে সিরিয়া চলে যায় এবং সেখানেই নিহত হয়।\n\nএরপর মদিনার শীর্ষ ধনী ও বীর আবু তালহা তাঁকে বিয়ের প্রস্তাব দেন। উম্মে সুলাইম দ্ব্যর্থহীন কণ্ঠে ঘোষণা দেন: \"হে আবু তালহা! আপনি পাথরের মূর্তিপূজা করেন যা কোনো লাভ বা ক্ষতি করতে পারে না। আপনি যদি ইসলাম গ্রহণ করেন তবে আপনার ইসলাম গ্রহণই হবে আমার একমাত্র দেনমোহর; আমি কোনো স্বর্ণমুদ্রা চাই না!\" আবু তালহা ইসলাম গ্রহণ করলেন। সাহাবিরা বলতেন: \"উম্মে সুলাইমের দেনমোহরের চেয়ে সম্মানিত দেনমোহর ইসলামের ইতিহাসে আর কারও ছিল না!\"\n\nতিনি রাসুলুল্লাহ (সা.)-এর খেদমতে নিজের ১০ বছরের সন্তান আনাসকে চিরদিনের জন্য সঁপে দিয়েছিলেন। উহুদ ও হুনাইনের যুদ্ধে তিনি কোমরে খঞ্জর বেঁধে রাসুলের প্রতিরক্ষায় যুদ্ধক্ষেত্রের অগ্রভাগে ছিলেন। তাঁর এক ছোট সন্তান যখন অসুস্থ হয়ে মারা যায়, আবু তালহা তখন বাইরে ছিলেন। উম্মে সুলাইম সন্তানকে চাদর দিয়ে ঢেকে রেখে স্বামীকে রাতের খাবার খাওয়ালেন এবং স্বামীর সাথে রাত কাটালেন। সকালে স্বামীকে জিজ্ঞাসা করলেন: \"কেউ যদি কোনো আমানত ধার দেয় এবং পরে তা ফেরত চায়, তবে কি তাকে বাধা দেওয়া যায়?\" আবু তালহা বললেন: \"না।\" তখন উম্মে সুলাইম বললেন: \"আল্লাহ তাঁর আমানত ফিরিয়ে নিয়েছেন!\" এই চরম সবরের বরকতে আল্লাহ তাঁদের এক নতুন পুত্র সন্তান দান করেন যার বংশধরের সকলেই মদিনার শ্রেষ্ঠ আলেম হয়েছিলেন।",
