    "birthAndDeathBn": "জন্ম: মক্কা | ওফাত: ৪৪ হিজরি মদিনা",
    "summaryBn": "কুরাইশ সর্দার আবু সুফিয়ানের কন্যা যিনি পিতার বিরোধিতা করে হাবশায় হিজরত করেছিলেন; সুদূর আবিসিনিয়ার মাটিতে যাঁর অভিভাবক হয়ে বাদশাহ নাজ্জাশি রাসুল (সা.)-এর সাথে বিবাহ সম্পন্ন করেছিলেন এবং যিনি পিতা কাফের থাকা অবস্থায় রাসুলের বিছানায় বসতে দেননি।",
    "detailedBiographyBn": "হযরত উম্মে হাবিবা রামলা বিনতে আবি সুফিয়ান (রা.) ছিলেন মক্কার প্রধান নেতা আবু সুফিয়ানের কন্যা এবং উমাইয়া খলিফা মুয়াবিয়ার বোন। কুরাইশদের শীর্ষ নেতার মেয়ে হওয়া সত্ত্বেও তিনি সত্যের আহ্বানে সাড়া দিয়ে স্বামী উবায়দুল্লাহ ইবনে জাহশসহ মক্কার সূচনাতেই ইসলাম গ্রহণ করেন।\n\nপিতার রোষানল থেকে বাঁচতে তিনি স্বামীকে নিয়ে আবিসিনিয়ায় হিজরত করেন। কিন্তু হাবশায় পৌঁছার পর এক নিদারুণ ট্র্যাজেডি ঘটে—তাঁর স্বামী উবায়দুল্লাহ খ্রিস্টধর্ম গ্রহণ করে মুরতাদ হয়ে যায় এবং মদ খেয়ে মৃত্যুবরণ করে। উম্মে হাবিবা বিদেশের মাটিতে একাকী অসহায় হয়ে পড়েন কিন্তু ঈমানের ওপর অবিচল থাকেন।\n\nরাসুলুল্লাহ (সা.) যখন এই খবর পেলেন, তখন ৭ হিজরিতে তিনি হাবশার বাদশাহ নাজ্জাশির কাছে চিঠি পাঠিয়ে উম্মে হাবিবাকে বিবাহের পয়গাম দেন। বাদশাহ নাজ্জাশি অত্যন্ত আনন্দিত হয়ে চারশত স্বর্ণমুদ্রা দেনমোহর নিজের রাজকোষ থেকে প্রদান করে স্বয়ং উম্মে হাবিবার বিবাহ সম্পন্ন করেন এবং রাজকীয় জাহাজে করে তাঁকে মদিনায় পাঠিয়ে দেন।\n\nমক্কা বিজয়ের পূর্বে আবু সুফিয়ান যখন হুদায়বিয়ার চুক্তি নবায়ন করতে মদিনায় আসে, তখন সে মেয়ে উম্মে হাবিবার ঘরে ঢোকে। আবু সুফিয়ান রাসুল (সা.)-এর বিছানায় বসতে গেলে উম্মে হাবিবা দ্রুত বিছানাটি গুটিয়ে সরিয়ে ফেলেন। আবু সুফিয়ান বিস্মিত হয়ে বলল: \"বেটি! এই বিছানা কি আমার জন্য অতিরিক্ত ভালো নাকি আমি এই বিছানার জন্য অতিরিক্ত ভালো?\" উম্মে হাবিবা নির্ভীক কণ্ঠে বললেন: \"এটি আল্লাহর রাসুল (সা.)-এর পবিত্র বিছানা, আর তুমি একজন অপবিত্র মুশরিক! আমি চাই না কোনো অপবিত্র মুশরিক রাসুলের বিছানায় বসুক!\"",
    "islamAcceptanceBn": "পিতার ঘোর শত্রুতা সত্ত্বেও প্রাথমিক দিনগুলোতেই মক্কায় ইসলাম গ্রহণ করেন।",
