    "summaryBn": "উম্মুল মুমিনীন খাদিজা (রা.)-এর ওফাত পরবর্তী চরম শোকের সময়ে রাসুলুল্লাহ (সা.)-এর সাথে বিবাহবন্ধনে আবদ্ধ হওয়া প্রবীণা নারী সাহাবি; যিনি রাসুলের অনাথ এতিম কন্যাদের পরম মমতায় লালন-পালন করেছিলেন এবং যাঁর দানশীলতা ছিল কিংবদন্তিতুল্য।",
    "detailedBiographyBn": "হযরত সাওদা বিনতে জামআ (রা.) ছিলেন কুরাইশ বংশের বনু আমির শাখার সন্তান। তিনি ও তাঁর প্রথম স্বামী সাকরান ইবনে আমর মক্কার সূচনাতেই ইসলাম গ্রহণ করে হাবশায় হিজরত করেন। হাবশা থেকে মক্কায় ফেরার পর সাকরান ইন্তেকাল করেন। বিধবা ও নিঃস্ব সাওদা চরম কষ্টে দিনাতিপাত করছিলেন।\n\nনবুওয়াতের দশম বর্ষে যখন উম্মুল মুমিনীন খাদিজা (রা.) এবং চাচা আবু তালেব ইন্তেকাল করলেন, রাসুল (সা.) ঘরে একা হয়ে পড়লেন। ছোট ছোট কন্যারা মাতৃহীন হয়ে পড়েছিল। খাওলা বিনতে হাকিম রাসুলকে সাওদার কথা বললেন। রাসুলুল্লাহ (সা.) একজন আশ্রয়হীনা বিধবা বৃদ্ধাকে সম্মান দিতে এবং নিজের পরিবারকে আগলে রাখতে সাওদাকে বিবাহ করেন। আয়েশা (রা.) আসার পূর্ব পর্যন্ত টানা তিন বছর সাওদা একা রাসুলের ঘরে থেকে ফাতিমা ও উম্মে কুলসুমকে মায়ের স্নেহে বড় করেন।\n\nসাওদা (রা.) ছিলেন অত্যন্ত সরলমনা, উদার ও দানশীল। একবার খলিফা উমর (রা.) তাঁর কাছে এক থলে দিরহাম পাঠালে তিনি সেই মুহূর্তেই দাসীদের ডেকে পুরো থলে মদিনার গরিবদের মাঝে বিলিয়ে দেন। তিনি আয়েশা (রা.)-কে এতো ভালোবাসতেন যে নিজের পালার দিনটি স্বেচ্ছায় আয়েশাকে উপহার দিয়েছিলেন যাতে রাসুল সন্তুষ্ট হন এবং জান্নাতে তিনি রাসুলের স্ত্রী হিসেবে পুনরুত্থিত হতে পারেন।",
    "islamAcceptanceBn": "মক্কার সূচনাতেই স্বামীর সাথে ইসলাম গ্রহণ করেন এবং হাবশায় হিজরত করেন।",
