    "birthAndDeathBn": "জন্ম: মদিনার উপকণ্ঠ | ওফাত: ৫০ বা ৫৬ হিজরি মদিনা (৬৫ বছর)",
    "summaryBn": "বনু মুস্তালিক গোত্রের সর্দারের কন্যা; যাঁর সাথে রাসুলুল্লাহ (সা.)-এর বিবাহের কারণে সাহাবিরা বনু মুস্তালিকের একশত পরিবারের সমস্ত যুদ্ধবন্দিকে এক নিমেষে নিঃশর্ত মুক্তি দিয়েছিলেন; যাঁর সম্পর্কে আয়েশা (রা.) বলেছিলেন: \"নিজ কওমের জন্য জুওয়াইরিয়ার চেয়ে বড় বরকতময়ী নারী ইতিহাসে আর কেউ ছিল না!\"",
    "detailedBiographyBn": "হযরত জুওয়াইরিয়া (রা.) ছিলেন বনু মুস্তালিক গোত্রের প্রধান হারিস ইবনে আবি জিরারের কন্যা। জাহেলি যুগে তাঁর নাম ছিল ‘বাররাহ’; রাসুল (সা.) তাঁর নাম রাখেন ‘জুওয়াইরিয়া’। ৫ বা ৬ হিজরিতে বনু মুস্তালিক যুদ্ধে তাদের পরাজয় ঘটলে জুওয়াইরিয়াসহ গোত্রের বহু নারী-পুরুষ বন্দি হন। জুওয়াইরিয়া দাসী হিসেবে সাহাবি সাবিত ইবনে কায়েসের ভাগে পড়েন।\n\nজুওয়াইরিয়া ছিলেন অত্যন্ত রূপবতী, আত্মমর্যাদাশীল ও বুদ্ধিমতী। তিনি নিজের মুক্তির জন্য নির্দিষ্ট পরিমাণ অর্থের বিনিময়ে চুক্তি (মুকাতাবাত) করতে চান। এই অর্থ পরিশোধের সাহায্যের জন্য তিনি রাসুলুল্লাহ (সা.)-এর দরবারে হাজির হয়ে নিজের পরিচয় দিয়ে আবেদন করেন।\n\nরাসুলুল্লাহ (সা.) তাঁর দুঃখ দেখে বললেন: \"তুমি কি এর চেয়ে উত্তম কিছু চাও?\" জুওয়াইরিয়া বললেন: \"হে আল্লাহর রাসুল! তা কী?\" রাসুল (সা.) বললেন: \"আমি তোমার সমস্ত মুক্তিপণ পরিশোধ করে দেব এবং তোমাকে বিবাহ করব!\" জুওয়াইরিয়া সানন্দে রাজি হলেন। এই বিবাহের সংবাদ মদিনায় ছড়িয়ে পড়ামাত্র সাহাবিদের মাঝে এক বিদ্যুৎচমকের মতো আলোড়ন সৃষ্টি হলো। সমস্ত সাহাবি চিৎকার করে বললেন: \"বনু মুস্তালিকের লোকেরা তো এখন রাসুলুল্লাহ (সা.)-এর শ্বশুরবাড়ির আত্মীয়! রাসুলের আত্মীয়রা আমাদের দাস হয়ে থাকতে পারে না!\" সাথে সাথে সাহাবিরা নিজেদের ভাগে থাকা বনু মুস্তালিকের একশত পরিবারের সমস্ত যুদ্ধবন্দিকে কোনো অর্থ ছাড়াই তৎক্ষণাৎ মুক্ত করে দিলেন! একটি বিবাহের বরকতে পুরো গোত্র ইসলাম গ্রহণ করে স্বাধীন হয়ে গেল।",
    "islamAcceptanceBn": "বনু মুস্তালিক যুদ্ধের পর রাসুলুল্লাহ (সা.)-এর সাথে বিবাহের মাধ্যমে ইসলাম গ্রহণ করেন।",
