    "detailedBiographyBn": "হযরত সাফিয়্যাহ (রা.) ছিলেন মদিনার বিখ্যাত ইহুদি গোত্র বনু নাদিরের প্রধান হুয়াই ইবনে আখতাবের কন্যা। হুয়াই ছিল রাসুল (সা.)-এর অন্যতম ঘোর শত্রু। সাফিয়্যাহ ছিলেন অত্যন্ত রূপবতী ও বুদ্ধিমতী। ৭ হিজরিতে খায়বারের সুরক্ষিত কামূস দুর্গ বিজিত হলে সাফিয়্যাহ যুদ্ধবন্দি হন।\n\nসাহাবিরা রাসুল (সা.)-কে বললেন: \"হে আল্লাহর রাসুল! সাফিয়্যাহ কুরাইজা ও নাদিরের প্রধান নেতার কন্যা, তিনি একমাত্র আপনারই সম্মান ও মর্যাদার উপযুক্ত!\" রাসুলুল্লাহ (সা.) তাঁকে ডেকে ইসলাম গ্রহণের প্রস্তাব দেন। সাফিয়্যাহ সানন্দে ইসলাম গ্রহণ করেন। রাসুল তাঁকে মুক্ত করে দিয়ে সেই মুক্তিকরণকেই দেনমোহর বানিয়ে বিবাহ করেন।\n\nসাফিয়্যাহ ছিলেন একনিষ্ঠ রাসুলপ্রেমিক ও সত্যবাদী নারী। অন্য স্ত্রীরা কখনো কখনো তাঁকে ইহুদি বংশের খোঁচা দিলে তিনি কেঁদে ফেলতেন। একদিন রাসুল (সা.) ঘরে ঢুকে তাঁকে কাঁদতে দেখে কারণ জিজ্ঞাসা করলেন। সাফিয়্যাহ বললেন: \"আয়েশা ও হাফসা আমাকে নিয়ে গর্ব করে বলে তারা কুরাইশ বংশের রাসুলের আত্মীয়, আর আমি এক ইহুদির মেয়ে!\" রাসুল (সা.) পরম স্নেহে তাঁর চোখের পানি মুছে দিয়ে বললেন: \"তুমি তাদের কেন বললে না—তোমরা আমার চেয়ে শ্রেষ্ঠ কীভাবে হতে পারো যখন হারুন (আ.) হলেন আমার পিতা, মূসা (আ.) হলেন আমার চাচা আর মুহাম্মদ (সা.) হলেন আমার স্বামী!\" সাফিয়্যাহ এই সান্ত্বনায় পরম আনন্দ লাভ করেন। তিনি আজীবন চরম দানশীল ও দয়ালু ছিলেন।",
    "islamAcceptanceBn": "৭ হিজরিতে খায়বার বিজয়ের পর রাসুলুল্লাহ (সা.)-এর সামনে এসে সানন্দে ইসলাম গ্রহণ করেন।",
