    "birthAndDeathBn": "জন্ম: মক্কা | ওফাত: ৫১ হিজরি সারিফ (৮০ বছর)",
    "summaryBn": "রাসুলুল্লাহ (সা.)-এর পবিত্র স্ত্রীদের মধ্যে সর্বশেষ বিবাহিত উম্মুল মুমিনীন; ৭ হিজরির ওমরাতুল কাজার সময় মক্কার অদূরে সারিফ নামক স্থানে যাঁর সাথে বিবাহ হয়েছিল এবং কাকতালীয়ভাবে সেই একই স্থানেই বহু বছর পর যাঁর ওফাত ও দাফন হয়েছিল।",
    "detailedBiographyBn": "হযরত মায়মুনা বিনতে হারিস আল-হিলালিয়াহ (রা.) ছিলেন উম্মুল মুমিনীন খাদিজা ও আয়েশার পর অত্যন্ত সম্মানিত এক নারী। তাঁর বোন উম্মুল ফজল ছিলেন রাসুলের চাচা আব্বাস (রা.)-এর স্ত্রী এবং বিখ্যাত সেনাপতি খালিদ বিন ওয়ালিদ ছিলেন তাঁর আপন ভাগিনা। তাঁর মূল নাম ছিল ‘বাররাহ’; রাসুলুল্লাহ (সা.) ওমরাতুল কাজার স্মৃতিতে তাঁর নাম রাখেন ‘মায়মুনা’ (বরকতময়ী)।\n\n৭ হিজরিতে রাসুলুল্লাহ (সা.) হুদায়বিয়ার ক্ষতিপূরণ হিসেবে কাজা ওমরাহ আদায় করতে মক্কায় আসেন। তখন মায়মুনার স্বামী মারা যাওয়ায় তিনি একাকী ছিলেন। চাচা আব্বাস (রা.) রাসুলের কাছে মায়মুনার বিবাহের প্রস্তাব দেন। রাসুল (সা.) তা কবুল করেন এবং মক্কা থেকে ফেরার পথে মক্কার অদূরে ‘সারিফ’ নামক স্থানে তাঁর সাথে রাসুলের বাসর সম্পন্ন হয়।\n\nমায়মুনা (রা.) ছিলেন চরম তাকওয়াবান ও আত্মীয়তার সম্পর্ক রক্ষাকারী। উম্মুল মুমিনীন আয়েশা (রা.) তাঁর প্রশংসায় বলেছিলেন: \"মায়মুনা আমাদের মধ্যে সবচেয়ে বেশি আল্লাহভীরু এবং আত্মীয়তার সম্পর্ক রক্ষায় সবচেয়ে বেশি অগ্রণী ছিলেন!\" তিনি ৭৬টি হাদিস বর্ণনা করেছেন। জীবনের শেষ ভাগে ৫১ হিজরিতে হজের সফর থেকে ফেরার পথে ঠিক সেই ‘সারিফ’ নামক প্রান্তরেই তিনি অসুস্থ হয়ে ইন্তেকাল করেন যেখানে রাসুলের সাথে তাঁর বিবাহ হয়েছিল! ইবনে আব্বাস (রা.) তাঁর জানাজায় ইমামতি করেন।",
