    "summaryBn": "রাসুলুল্লাহ (সা.)-এর ফুফাতো বোন ও উম্মুল মুমিনীন; যাঁর সাথে রাসুল (সা.)-এর বিবাহ কোনো কাজী বা সাক্ষীর মাধ্যমে হয়নি বরং স্বয়ং মহান আল্লাহ সাত আসমানের ওপর থেকে সম্পন্ন করেছিলেন; যিনি রাসুলের ওফাতের পর উম্মুল মুমিনীনদের মধ্যে সবার আগে ইন্তেকাল করেন।",
    "detailedBiographyBn": "হযরত যায়নাব বিনতে জাহশ (রা.) ছিলেন রাসুলুল্লাহ (সা.)-এর আপন ফুফু উমাইমা বিনতে আব্দুল মুত্তালিবের কন্যা। কুরাইশদের অত্যন্ত সম্মানিত ঘরের কন্যা হওয়া সত্ত্বেও রাসুলের নির্দেশে তিনি সাবেক ক্রীতদাস যায়েদ বিন হারেসা (রা.)-কে বিবাহ করে শ্রেণিভেদ দূর করার দৃষ্টান্ত স্থাপন করেন। কিন্তু পরবর্তীতে তাঁদের বনিবনা না হওয়ায় যায়েদ তাঁকে তালাক দেন।\n\nজাহেলি যুগে দত্তক নেওয়া পুত্রকে আপন পুত্রের মতো মনে করা হতো এবং দত্তক পুত্রের তালাকপ্রাপ্তা স্ত্রীকে বিবাহ করা নিষিদ্ধ ছিল। আল্লাহ তাআলা এই কুসংস্কার চিরতরে বিলুপ্ত করার জন্য রাসুলুল্লাহ (সা.)-কে যায়নাবের সাথে বিবাহের নির্দেশ দেন। পবিত্র কুরআনের সূরা আহযাবের ৩৭ নম্বর আয়াতে স্বয়ং আল্লাহ ঘোষণা করেন: \"অতঃপর যায়েদ যখন তার সাথে সম্পর্ক ছিন্ন করল, তখন আমি (আল্লাহ) তাকে তোমার সাথে বিবাহবন্ধনে আবদ্ধ করলাম!\"\n\nযায়নাব (রা.) অন্যান্য উম্মুল মুমিনীনদের সামনে গর্ব করে বলতেন: \"তোমাদের বিয়ে তোমাদের পরিবার ও অভিভাবকরা জমিনে পড়িয়েছে, আর আমার বিয়ে স্বয়ং মহান রাব্বুল আলামিন সাত আসমানের ওপর থেকে পড়িয়েছেন!\"\n\nতিনি নিজ হাতে পশুর চামড়া পাকা করতেন, সুঁই-সুতো দিয়ে জিনিসপত্র বানিয়ে বাজারে বিক্রি করতেন এবং উপার্জিত সমস্ত অর্থ নিঃস্ব ও এতিমদের মাঝে বিলিয়ে দিতেন। রাসুল (সা.) একবার স্ত্রীদের বলেছিলেন: \"তোমাদের মধ্যে যে দীর্ঘ হাতের অধিকারী (সবচেয়ে বেশি দানশীল), সে আমার মৃত্যুর পর সবার আগে আমার সাথে এসে মিলিত হবে!\" ২০ হিজরিতে তিনিই প্রথম স্ত্রী হিসেবে রাসুলের সান্নিধ্যে চলে যান।",
    "islamAcceptanceBn": "মক্কার প্রারম্ভিক যুগেই পরিবারের সাথে ইসলাম গ্রহণ করেন এবং হাবশায় হিজরত করেন।",
