        "story": "উম্মুল মুমিনীন আয়েশা (রা.) বর্ণনা করেন: রাসুলুল্লাহ (সা.)-এর ওফাতের পর আমরা সমস্ত স্ত্রীরা প্রায়ই একত্রিত হয়ে ঘরের দেয়ালের সাথে হাত মেপে দেখতাম কার হাত কতটুকু লম্বা! কারণ রাসুল বলেছিলেন যার হাত সবচেয়ে লম্বা সে সবার আগে তাঁর সাথে মিলবে। আমরা দেখলাম সাওদার হাত সবচেয়ে লম্বা। কিন্তু ২০ হিজরিতে যখন সবার আগে যায়নাব বিনতে জাহশ ইন্তেকাল করলেন, তখন আমরা আসল রহস্য বুঝতে পারলাম! রাসুল হাত লম্বা বলতে শারীরিক দৈর্ঘ্য বোঝাননি, বরং দানশীলতার হাত কার কত বড় তা বুঝিয়েছিলেন! যায়নাব দিনরাত নিজের হাতে হস্তশিল্প তৈরি করে সমস্ত অর্থ গরিবদের দান করে দিতেন।"
