    "summaryBn": "রাসুলুল্লাহ (সা.) ও খাদিজা (রা.)-এর রূপবতী দ্বিতীয়া কন্যা; যিনি হযরত উসমান (রা.)-এর সাথে হাবশায় ও মদিনায় দুইবার হিজরত করেছিলেন এবং বদর যুদ্ধের বিজয়ের শুভ মুহূর্তে যাঁর জানাজা মদিনায় সম্পন্ন হয়েছিল।",
    "detailedBiographyBn": "হযরত রুকাইয়া (রা.) ছিলেন রাসুলুল্লাহ (সা.) ও খাদিজা (রা.)-এর দ্বিতীয়া কন্যা। নবুওয়াতের পূর্বে আবু লাহাবের পুত্র উতবার সাথে তাঁর বিবাহ ঠিক হয়েছিল। কিন্তু যখন সূরা লাহাব নাজিল হলো, আবু লাহাব ও উম্মে জামিল পুত্রকে বাধ্য করে রুকাইয়াকে তালাক দেওয়ায়। এটি ছিল আল্লাহর এক বিশেষ রহমত।\n\nপরবর্তীতে রাসুলুল্লাহ (সা.) কুরাইশদের শীর্ষ তরুণ ও ধনী হযরত উসমান ইবনে আফফান (রা.)-এর সাথে রুকাইয়াকে বিবাহ দেন। তাঁরা ছিলেন মক্কার সবচেয়ে রূপবান ও আকর্ষণীয় দম্পতি। কুরাইশদের অত্যাচার শুরু হলে উসমান রুকাইয়াকে নিয়ে হাবশায় প্রথম হিজরতকারীদের অন্তর্ভুক্ত হন। রাসুল (সা.) বলেছিলেন: \"লুত (আ.)-এর পর উসমান ও রুকাইয়াই হলো প্রথম দম্পতি যারা সপরিবারে আল্লাহর জন্য হিজরত করেছে।\"\n\nমদিনায় হিজরতের পর ২ হিজরিতে ঐতিহাসিক বদর যুদ্ধের সময় রুকাইয়া মারাত্মক গুটিবসন্ত রোগে আক্রান্ত হয়ে শয্যাশায়ী হন। উসমান (রা.) বদরে যাওয়ার জন্য প্রস্তুত হলে রাসুল (সা.) উসমানকে মদিনায় থেকে রুকাইয়ার সেবার নির্দেশ দেন এবং বলেন: \"উসমান! তুমি বদরে অংশগ্রহণকারীর পূর্ণ সওয়াব ও গনিমতের অংশ পাবে!\" ১৭ রমজান যেদিন যায়েদ বিন হারেসা বদর বিজয়ের সুসংবাদ নিয়ে মদিনায় প্রবেশ করলেন, ঠিক সেই মুহূর্তে রুকাইয়া শেষ নিঃশ্বাস ত্যাগ করেন এবং সাহাবিরা তাঁর দাফন সম্পন্ন করছিলেন।",
    "islamAcceptanceBn": "মা খাদিজার সাথে শৈশবেই ইসলামের সূচনাতে ইসলাম গ্রহণ করেন।",
