    "detailedBiographyBn": "হযরত উম্মে কুলসুম (রা.) ছিলেন রাসুলুল্লাহ (সা.) ও খাদিজা (রা.)-এর তৃতীয়া কন্যা। জাহেলি যুগে আবু লাহাবের অপর পুত্র উতাইবা বিনতে উম্মে জামিলের সাথে তাঁর বিয়ে ঠিক হয়েছিল, কিন্তু সূরা লাহাবের পর উতাইবা রাসুল (সা.)-এর সাথে চরম বেয়াদবি করে উম্মে কুলসুমকে তালাক দেয়।\n\nমক্কায় নবুওয়াতের কঠিন বছরগুলোতে এবং শিয়াবে আবি তালিবে তিন বছর অনাহারে অবরুদ্ধ থাকার দিনগুলোতে উম্মে কুলসুম পিতা রাসুল (সা.) ও মাতা খাদিজার পাশে একনিষ্ঠভাবে অবস্থান করেন। মা খাদিজার ওফাতের পর তিনি ঘরকন্নার দায়িত্ব কাঁধে তুলে নেন।\n\n২ হিজরিতে বড় বোন রুকাইয়া ইন্তেকাল করলে খলিফা উসমান (রা.) গভীর শোকে ভেঙে পড়েন। ৩ হিজরির রবিউল আউয়াল মাসে রাসুলুল্লাহ (সা.) উম্মে কুলসুমকে উসমানের সাথে বিবাহ দেন। একজন নবির দুই কন্যাকে একের পর এক বিবাহ করার কারণেই উসমান (রা.) ইতিহাসে ‘জুন-নুরাইন’ (দুই জ্যোতির অধিকারী) উপাধিতে ভূষিত হন। উম্মে কুলসুম টানা ছয় বছর উসমানের সাথে অত্যন্ত সুখময় দাম্পত্য জীবন কাটান। ৯ হিজরির শাবান মাসে মাত্র ২৭ বছর বয়সে কোনো সন্তান না রেখেই তিনি ইন্তেকাল করেন। রাসুল (সা.) নিজ হাতে স্নেহের কন্যার জানাজায় ইমামতি করেন এবং কবরের পাশে বসে নীরবে অশ্রু বিসর্জন করেন।",
    "islamAcceptanceBn": "শৈশবেই মাতা খাদিজা ও বোনদের সাথে একযোগে ইসলাম গ্রহণ করেন।",
