    "birthAndDeathBn": "জন্ম: মক্কা | ওফাত: ৪ হিজরি মদিনা",
    "summaryBn": "আবু তালেবের স্ত্রী ও হযরত আলী (রা.)-এর মা; দাদা আব্দুল মুত্তালিবের মৃত্যুর পর যিনি শৈশবে এতিম রাসুলুল্লাহ (সা.)-কে নিজের সন্তানদের চেয়েও বেশি ভালোবেসে মায়ের স্নেহে লালন-পালন করেছিলেন; যাঁর কাফনের জন্য রাসুল নিজের গায়ের জামা দিয়েছিলেন।",
    "detailedBiographyBn": "হযরত ফাতিমা বিনতে আসাদ (রা.) ছিলেন কুরাইশ বংশের বনু হাশিম শাখার সম্মানিত নারী। তিনি ছিলেন রাসুলের আপন চাচা আবু তালেবের স্ত্রী এবং জাফর, আকিল ও আলী (রা.)-এর মাতা। রাসুলুল্লাহ (সা.)-এর বয়স যখন মাত্র ৮ বছর এবং তাঁর দাদা আব্দুল মুত্তালিব ইন্তেকাল করেন, তখন আবু তালেব রাসুলকে নিজ ঘরে নিয়ে আসেন।\n\nফাতিমা বিনতে আসাদ শিশু মুহাম্মদকে এমন নিঃস্বার্থ ভালোবাসায় আগলে রাখতেন যা নিজের সন্তানদের ক্ষেত্রেও দেখা যেত না। ভালো খাবার থাকলে নিজের সন্তানদের না দিয়ে আগে মুহাম্মদকে খাওয়াতেন, নিজ হাতে তাঁর চুল আঁচড়ে দিতেন এবং গায়ে সুগন্ধি মাখিয়ে দিতেন। রাসুল (সা.) আজীবন তাঁকে ‘উম্মি’ (আমার মা) বলে ডাকতেন।\n\nনবুওয়াতের সূচনালগ্নেই তিনি স্বামী আবু তালেবের জীবদ্দশাতেই ইসলাম গ্রহণ করেন এবং নারীদের মধ্যে অন্যতম অগ্রণী ছিলেন। পরবর্তীতে তিনি মদিনায় হিজরত করেন। ৪ হিজরিতে যখন তিনি ইন্তেকাল করেন, রাসুলুল্লাহ (সা.) কান্নায় ভেঙে পড়েন এবং বলেন: \"আজ আমার মা মারা গেলেন!\" রাসুলুল্লাহ (সা.) নিজের পরিহিত গায়ের জামা মোবারক খুলে ফাতিমা বিনতে আসাদের কাফন হিসেবে পরিয়ে দেন এবং কবরের মাটির চাপ লাঘব করার জন্য রাসুল নিজে কবরের ভেতরে নেমে কিছুক্ষণ শুয়ে দোয়া করেন।",
    "islamAcceptanceBn": "মক্কার সূচনাতেই খাদিজার পর প্রাথমিক নারীদের অন্যতম হয়ে ইসলাম গ্রহণ করেন।",
