    "summaryBn": "রাসুলুল্লাহ (সা.)-এর পিতা আব্দুল্লাহর আবিসিনীয় দাসী, যিনি রাসুলের জন্মের সময় উপস্থিত ছিলেন এবং মা আমেনার মৃত্যুর পর অবোয়া থেকে রাসুলকে মক্কায় কোলে নিয়ে এসেছিলেন; যাঁর জন্য রাসুল বলতেন: \"উম্মে আইমান আমার মায়ের পর আমার মা!\"",
    "detailedBiographyBn": "হযরত উম্মে আইমান বারাকা বিনতে সালাবা (রা.) ছিলেন আবিসিনীয় বংশোদ্ভূত এক পুণ্যবতী নারী। তিনি রাসুলুল্লাহ (সা.)-এর পিতা আব্দুল্লাহর মৃত্যুর পর উত্তরাধিকার সূত্রে রাসুলের পরিবারে আসেন। রাসুলের যখন জন্ম হয়, তখন বারাকাই প্রথম কোলে নিয়েছিলেন। রাসুলের বয়স যখন মাত্র ৬ বছর এবং মা আমেনা মদিনা থেকে ফেরার পথে অবোয়া নামক মরুভূমিতে ইন্তেকাল করেন, তখন বারাকাই মরুভূমির মাঝে একা অবুঝ এতিম শিশু মুহাম্মদকে জড়িয়ে ধরে কেঁদেছিলেন এবং কোলে করে মক্কায় দাদার কাছে পৌঁছে দেন।\n\nরাসুলুল্লাহ (সা.) নবুওয়াত পেয়ে বারাকাকে মুক্ত করে দেন এবং যায়েদ বিন হারেসার সাথে তাঁর বিবাহ দেন। তাঁদের সন্তানই ছিলেন প্রিয়তম উসামা ইবনে যায়েদ। রাসুল (সা.) উম্মে আইমানকে দেখে বলতেন: \"ইনি হলেন আমার পরিবারের একমাত্র অবশিষ্ট সদস্য এবং আমার মায়ের পর আমার মা!\"\n\nউম্মে আইমান একা পায়ে হেঁটে মক্কায় মরুভূমির তীব্র রোদে পিপাসায় কাতর হয়ে মদিনায় হিজরত করেছিলেন। উহুদের যুদ্ধে তিনি মুজাহিদদের পানি পান করাতেন এবং হুনাইনে রাসুলের পাশে ছিলেন। রাসুল (সা.)-এর ওফাতের পর আবু বকর ও উমর (রা.) নিয়মিত উম্মে আইমানের বাড়ি যেতেন তাঁর খোঁজখবর নিতে যেমনটি রাসুল যেতেন। আবু বকর ও উমরকে দেখে তিনি কাঁদতেন, কারণ আসমান থেকে ওহী নাজিলের সিলসিলা চিরতরে বন্ধ হয়ে গেছে।",
