    "summaryBn": "জাহেলি যুগে আরবের হাতেগোনা শিক্ষিত নারীদের অন্যতম; ইসলামের ইতিহাসের সর্বপ্রথম নারী শিক্ষিকা যিনি উম্মুল মুমিনীন হাফসাকে লেখাপড়া শিখিয়েছিলেন; খলিফা উমর ফারুক (রা.) যাঁর অসাধারণ সততা ও বুদ্ধিমত্তার কারণে মদিনার বাজার পরিদর্শনের প্রশাসনিক দায়িত্ব দিয়েছিলেন।",
    "detailedBiographyBn": "হযরত শিফা বিনতে আব্দুল্লাহ আল-আদাবিয়্যাহ (রা.) ছিলেন খলিফা উমর ইবনুল খাত্তাব (রা.)-এর নিজ বনু আদি গোত্রের এক পরম বিদুষী ও প্রভাবশালী নারী। জাহেলি যুগে যখন আরবে অক্ষরজ্ঞানসম্পন্ন মানুষের সংখ্যা ছিল অত্যন্ত বিরল, তখন শিফা চমৎকার লিখতে, পড়তে ও ভেষজ চিকিৎসা করতে পারতেন।\n\nমক্কায় ইসলামের সূচনাতেই তিনি ইসলাম গ্রহণ করেন এবং প্রারম্ভিক মুহাজিরদের সাথে মদিনায় হিজরত করেন। রাসুলুল্লাহ (সা.) শিফাকে অত্যন্ত শ্রদ্ধা করতেন এবং প্রায়ই তাঁর বাড়িতে গিয়ে বিশ্রাম নিতেন। শিফা নিজ ঘরে একটি বিশেষ বিছানা ও চাদর কেবল রাসুল (সা.)-এর বিশ্রামের জন্য সংরক্ষণ করে রেখেছিলেন। রাসুল (সা.) শিফাকে উম্মুল মুমিনীন হাফসা বিনতে উমরকে সুন্দর হস্তাক্ষর ও চর্মরোগের ঝাড়ফুঁক শেখানোর নির্দেশ দিয়েছিলেন। ফলে তিনি ছিলেন ইসলামের ইতিহাসের প্রথম নারী শিক্ষিকা।\n\nখলিফা উমর (রা.) শিফার তীক্ষ্ণ মেধা, ইনসাফ ও সততার ওপর অগাধ আস্থা রাখতেন। উমর (রা.) তাঁকে মদিনার বাজারের বাণিজ্যিক লেনদেন তদারকি, ওজনে কারচুপি রোধ এবং বাজার পরিদর্শনের (মুহতাসিব) দায়িত্ব দিয়েছিলেন। তিনি মুসলিম সমাজের প্রশাসনিক ও বিচারিক পরামর্শে এক উজ্জ্বল দৃষ্টান্ত স্থাপন করেন। ২০ হিজরিতে মদিনায় তিনি ইন্তেকাল করেন।",
    "islamAcceptanceBn": "মক্কার সূচনাতেই ইসলাম গ্রহণ করেন এবং মদিনায় হিজরত করেন।",
