        "story": "শিফা (রা.) বলেন: একবার রাসুলুল্লাহ (সা.) আমার ঘরে এলেন, তখন হাফসা (রা.) আমার পাশে বসা ছিলেন। রাসুল (সা.) আমাকে বললেন: \"হে শিফা! তুমি যেভাবে হাফসাকে লেখা শিখিয়েছ, সেভাবে কি তাকে বিষাক্ত পোকার ক্ষতের ঝাড়ফুঁক ও ভেষজ চিকিৎসাও শিখিয়ে দেবে না?\" আমি অত্যন্ত আনন্দিত হয়ে হাফসাকে সেই দোয়া ও চিকিৎসা শিখিয়ে দিলাম। রাসুলুল্লাহ (সা.) আমার শিক্ষাদানের এই খেদমতে অত্যন্ত খুশি হয়ে আমাকে মদিনায় একটি বাড়ি উপহার হিসেবে নির্ধারণ করে দিয়েছিলেন।"
